insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('10f0334d-7b6e-4dbd-9023-56c4171f33f7', 'trabajo', 'practica', 'La fecha imposible',
   'Tres áreas querían la misma semana de lanzamiento. En lugar de decidir sola, Macarena abrió una hoja compartida: «Vamos a consensuar la fecha hoy; traigan sus dos peores semanas». En cuarenta minutos había una fecha y ningún enfado.',
   'Habría que ponernos de acuerdo en la fecha.', 'Vamos a consensuar la fecha hoy.', 1),
  ('10f0334d-7b6e-4dbd-9023-56c4171f33f7', 'familia', 'emocional', 'El viaje de los cuatro',
   'Cada año el viaje de verano acababa con alguien enfadado. Este año, Ernesto propuso otra cosa: «Consensuamos destino y presupuesto antes de mirar precios». Tardaron una tarde, pero por primera vez salieron los cuatro contentos.',
   'A ver si esta vez nos ponemos de acuerdo.', 'Consensuamos destino y presupuesto antes de mirar precios.', 2),
  ('10f0334d-7b6e-4dbd-9023-56c4171f33f7', 'social', 'social', 'El grupo del edificio',
   'El chat del edificio ardía por el horario de la obra. Una vecina escribió: «¿Y si lo consensuamos en diez minutos el sábado?». Se juntaron nueve personas en el portal y salió un horario que ninguna odiaba.',
   'A ver si llegamos a algo entre todos.', '¿Y si lo consensuamos el sábado?', 3);

