insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4526094d-785a-45d4-9cab-7bc8401c714e', 'trabajo', 'practica', 'Una idea al cierre',
   'La presentación tenía dieciocho diapositivas y Marta sabía que nadie recordaría dieciocho cosas. Cerró así: «Si solo se llevan una frase, quiero recalcar esta: el plazo es el 30 y no se mueve». Tres semanas después seguían citando la fecha.',
   'Y esto lo repito porque es lo importante.', 'Quiero recalcar esta idea: el plazo es el 30.', 1),
  ('4526094d-785a-45d4-9cab-7bc8401c714e', 'familia', 'emocional', 'Parar cada dos horas',
   'Cada vez que salgo de viaje, mi padre me acompaña al coche y dice lo mismo. «Te lo recalco: para cada dos horas, aunque no estés cansado». Lo dice con la mano en la ventanilla, y por eso paro siempre.',
   'Te lo digo otra vez porque es importante.', 'Te lo recalco: para cada dos horas.', 2),
  ('4526094d-785a-45d4-9cab-7bc8401c714e', 'entrevista', 'social', 'Seis meses seguidos',
   'Adriana contó su proyecto sin adornos y luego se detuvo un segundo. «Quiero recalcar un dato: entregamos a tiempo seis meses seguidos, con el mismo equipo». La entrevistadora subrayó esa línea en su cuaderno.',
   'Ah, y lo de los seis meses es importante.', 'Quiero recalcar un dato: seis meses seguidos.', 3);

