insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('81a39f4e-96f9-4a5c-9e7e-46a1429e6b0e', 'trabajo', 'practica', 'Los dos segundos del presupuesto',
   'Mariana llevaba la cifra exacta y aun así tardó dos segundos en decirla. Al salir comentó: «Titubeé y me molestó. La próxima vez la digo entera y me callo». Lo practicó en voz alta y en la siguiente reunión salió limpia.',
   'Me quedé trabada al decir el número.', 'Titubeé y me molestó.', 1),
  ('81a39f4e-96f9-4a5c-9e7e-46a1429e6b0e', 'familia', 'emocional', 'Por qué nos mudamos',
   'Mi sobrino preguntó en mitad de la merienda por qué nos íbamos de la casa. Dudé más de la cuenta buscando una versión suave. Al final le dije la verdad simple, y él siguió con su galleta. Titubear delante de un niño no sirve de nada.',
   'Me quedé sin saber qué decir.', 'Titubear delante de un niño no sirve de nada.', 2),
  ('81a39f4e-96f9-4a5c-9e7e-46a1429e6b0e', 'entrevista', 'social', 'El año que faltaba',
   'La pregunta llegó a mitad de la entrevista: el año sin trabajar. Camila se quedó un momento en blanco y luego contestó despacio. «Titubeé un segundo y seguí», contó después. La contrataron igual.',
   'Me quedé cortada un segundo y luego seguí.', 'Titubeé un segundo y seguí.', 3);

