insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('0350b6a1-30da-46dc-aaa7-93875ce8ef0c', 'entrevista', 'practica', 'Once candidatos',
   'Entrevistaron a once personas para el puesto de compras. Fernanda no tenía el currículo más largo, pero sí tres años en el mismo sector y un caso resuelto que podía contar. «Es la candidata idónea», dijo la responsable, y explicó por qué en dos frases.',
   'Creo que es la mejor para el puesto.', 'Es la candidata idónea.', 1),
  ('0350b6a1-30da-46dc-aaa7-93875ce8ef0c', 'trabajo', 'practica', 'El salón del segundo',
   'El taller no cabía en la sala de siempre y alguien propuso el salón del segundo piso. Buena luz, sillas que se mueven y una pared libre. «Es el espacio idóneo», resumió Héctor, y lo reservaron para los tres jueves siguientes.',
   'Ese sitio nos viene mejor para el taller.', 'Es el espacio idóneo.', 2),
  ('0350b6a1-30da-46dc-aaa7-93875ce8ef0c', 'familia', 'emocional', 'El momento de cambiar',
   'Llevaba dos años queriendo cambiar de trabajo y siempre faltaba algo. Este otoño coincidieron las dos cosas: el contrato terminaba y había ahorro para tres meses. Se lo dijo a su madre en la cocina: «Es el momento idóneo, y no va a repetirse pronto».',
   'Creo que ahora es buen momento.', 'Es el momento idóneo.', 3);

