insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('f65ae938-f92d-4d92-802e-d3e1e48cc606', 'entrevista', 'practica', 'Parecido no basta',
   'Renata no tenía el mismo recorrido que el resto del equipo y lo sabía. «Mi perfil no es idéntico, pero sí afín: trabajo con datos y con clientes a la vez, como ustedes», explicó. Le preguntaron por la parte de clientes durante diez minutos.',
   'Creo que mi perfil se parece bastante al del equipo.', 'Mi perfil no es idéntico, pero sí afín.', 1),
  ('f65ae938-f92d-4d92-802e-d3e1e48cc606', 'social', 'social', 'El club de los jueves',
   'El club de senderismo puso un cartel en la panadería: «Buscamos socios con intereses afines: andar despacio y leer en la cima». Se apuntaron nueve personas en dos semanas, y ninguna preguntó por el ritmo.',
   'Buscamos gente con gustos parecidos.', 'Buscamos socios con intereses afines.', 2),
  ('f65ae938-f92d-4d92-802e-d3e1e48cc606', 'familia', 'emocional', 'Cine en el salón',
   'Mi hermano y mi cuñada discuten por casi todo, menos por las películas. Ella pone el género, él pone la hora y siempre acaban de acuerdo. «En eso somos afines», dice él, y ella no lo desmiente.',
   'En eso tenemos gustos parecidos.', 'En eso somos afines.', 3);

