insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('963da377-c4db-44d6-afb9-19824efb3b51', 'social', 'social', 'La cena del viernes',
   'A Lorena la invitaron a una cena el mismo día que había prometido descansar. Contestó en dos líneas: «Me hace mucha ilusión, pero esta vez lo declino; avísame de la próxima». Nadie se molestó y la próxima llegó en quince días.',
   'Uf, es que no sé, mejor otro día.', 'Esta vez lo declino, avísame de la próxima.', 1),
  ('963da377-c4db-44d6-afb9-19824efb3b51', 'trabajo', 'practica', 'El encargo del jueves',
   'Le ofrecieron a Salvador coordinar un segundo equipo. Pidió una hora para mirar su calendario y respondió: «Declino el encargo; con los dos proyectos actuales no lo haría bien». Su responsable le agradeció la claridad.',
   'Es que no sé si voy a poder, la verdad.', 'Declino el encargo y te explico por qué.', 2),
  ('963da377-c4db-44d6-afb9-19824efb3b51', 'familia', 'emocional', 'El verano de siempre',
   'Carmen llevaba quince años yendo a la casa del pueblo en agosto. Este año llamó a su hermana antes de que hicieran los planes: «Voy a declinar lo de agosto, y quiero contártelo yo». Hablaron una hora y quedaron en septiembre.',
   'Este año creo que no voy a ir.', 'Voy a declinar lo de agosto.', 3);

