insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('9a3b91bf-2109-45bb-91f1-a79f0c700a0f', 'trabajo', 'practica', 'La tarifa y el tope',
   'El cliente quería cambios sin límite. Sara respiró y propuso: «Pactemos tres rondas de cambios; a partir de la cuarta, se factura aparte». Él lo pensó dos segundos y aceptó. El proyecto terminó en fecha.',
