insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('af2b7303-1cf9-416a-9e74-6c5fd2e67130', 'trabajo', 'practica', 'El sí con letra pequeña',
   'Le pedían la web para el día quince. Alicia no dijo que no: «Acepto, y condiciono la fecha a recibir los textos el lunes. Si llegan el miércoles, entrego el diecisiete». Llegaron el martes, y nadie discutió el diecisiete.',
