insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('6027c45c-0605-42b8-bdac-b5c2eb95f8ed', 'trabajo', 'practica', 'El total que asustaba',
   'El número final hizo que el cliente se echara atrás en la silla. Sandra no bajó el precio: «Déjame desglosarlo: diseño, programación, textos y dos meses de soporte». El cliente miró las cuatro líneas y solo quitó el soporte.',
