insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('ee10f865-558e-435e-a3c3-76bbead4668c', 'trabajo', 'practica', 'El resumen de los martes',
   'Diego había empezado a mandar un resumen de dos líneas después de cada reunión. Nadie lo pidió. Su jefa lo nombró en voz alta: «Quiero reforzar esto: el resumen de Diego nos ahorra correos». Al mes, lo mandaban cuatro personas más.',
   'Está muy bien lo que hace Diego.', 'Quiero reforzar esto: el resumen de Diego.', 1),
  ('ee10f865-558e-435e-a3c3-76bbead4668c', 'familia', 'emocional', 'La llamada del domingo',
   'Nadie decidió nunca que hubiera una llamada los domingos. Simplemente su madre siempre estaba al otro lado a la misma hora. «No hizo falta que nos lo pidiera», contaba Lorena años después. «Reforzó la costumbre estando, y eso pesó más que cualquier norma».',
   'Ella lo mantuvo sin decir nada.', 'Reforzó la costumbre estando siempre ahí.', 2),
  ('ee10f865-558e-435e-a3c3-76bbead4668c', 'social', 'social', 'Dos datos y una historia',
   'El grupo del barrio quería pedir un paso de peatones y nadie los escuchaba. Ernesto cambió la carta: «Vamos a reforzar la petición con dos datos y la historia del susto de marzo». La respuesta llegó en tres semanas.',
   'Hay que decirlo con más fuerza.', 'Vamos a reforzar la petición con datos.', 3);

