insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('67651582-60ff-4771-8ea8-a1d257fd968d', 'trabajo', 'practica', 'El correo de marzo',
   'La reunión iba bien hasta que alguien sacó un correo de hacía cinco meses. Marta respiró y lo dijo sin subir la voz: «Esto ya no lo podemos arreglar. ¿Me reprochas el correo o me pides algo para la semana que viene?». Se pidió algo, y se hizo.',
   'No me saques cosas de hace meses.', '¿Me reprochas el correo o me pides algo?', 1),
  ('67651582-60ff-4771-8ea8-a1d257fd968d', 'familia', 'emocional', 'Lo del verano',
   'En casa había una lista invisible que salía en cada discusión. Un domingo, Teresa la nombró: «No quiero reprocharte lo del verano otra vez. Quiero pedirte una cosa concreta para el que viene». Su hermano se sentó, y por primera vez escuchó entera la petición.',
   'Siempre acabo echándote en cara lo mismo.', 'No quiero reprocharte lo del verano otra vez.', 2),
  ('67651582-60ff-4771-8ea8-a1d257fd968d', 'social', 'social', 'La lista del piso',
   'Compartían piso desde septiembre y la convivencia se llenó de cuentas viejas. Álvaro propuso una regla: «Si algo tiene más de una semana, no se reprocha; se habla el domingo o se olvida». Funcionó tan bien que la copiaron en el piso de al lado.',
   'Dejemos de sacarnos cosas antiguas.', 'Si tiene más de una semana, no se reprocha.', 3);

