insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('cb5014f3-c402-4b41-9776-30a7ff7086c4', 'trabajo', 'practica', 'Antes de las cifras',
   'La reunión llevaba veinte minutos discutiendo números cuando Ariadna levantó la mano. «Un momento: estamos partiendo de una premisa que nadie ha dicho, que el equipo seguirá igual de grande». Se hizo un silencio corto. Volvieron a empezar con esa línea escrita arriba del todo.',
   'Estamos dando por hecho una cosa, ¿no?', 'Partimos de una premisa que nadie ha dicho.', 1),
  ('cb5014f3-c402-4b41-9776-30a7ff7086c4', 'familia', 'emocional', 'El local de marzo',
   'Mi hermano tenía el plan entero en una hoja: fechas, gente, comida. «¿Y el local?», le pregunté. Se quedó callado. «Toda la fiesta se apoya en una premisa: que estará libre en marzo». Llamó esa misma tarde y no lo estaba.',
   'Todo esto se cae si eso no es verdad.', 'Todo se apoya en una premisa: que estará libre.', 2),
  ('cb5014f3-c402-4b41-9776-30a7ff7086c4', 'social', 'social', 'La gente joven y los correos',
   'En el taller del barrio repetían que la gente joven no lee correos. Nerea lo escuchó tres veces y preguntó de dónde salía. Nadie supo decirlo. «Entonces es una premisa, no un dato», resumió, y esa semana probaron a escribir.',
   'Eso lo damos por hecho y ya está.', 'Entonces es una premisa, no un dato.', 3);

