insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('9dc71ca4-6819-4260-a0fe-70a71a38c846', 'trabajo', 'practica', 'Una línea antes de votar',
   'La reunión se alargaba y las ideas cambiaban cada diez minutos. Ximena propuso algo raro: escribir en una línea lo que cada uno iba a defender, antes de empezar. «Así tenemos una postura, no un humor». Se votó en veinte minutos.',
   'Yo lo veo así, más o menos.', 'Así tenemos una postura, no un humor.', 1),
  ('9dc71ca4-6819-4260-a0fe-70a71a38c846', 'entrevista', 'practica', 'El trabajo a distancia',
   '«¿Y qué opina usted del trabajo a distancia?», preguntó el entrevistador. Emilio no dio rodeos: «Le doy una postura, no una opinión: dos días en casa y los martes todos juntos». Le pidieron que la defendiera y la defendió.',
   'Pues hay cosas buenas y cosas malas.', 'Le doy una postura, no una opinión.', 2),
  ('9dc71ca4-6819-4260-a0fe-70a71a38c846', 'familia', 'emocional', 'El plan A y el plan B',
   'Marina había defendido el plan A durante semanas. Cuando vio los números nuevos, lo dijo en la misma cena: «Cambio de postura, y os cuento por qué». Nadie se lo echó en cara. Esa noche el plan B salió adelante con todos los votos.',
   'Pues ahora ya no lo veo tan claro.', 'Cambio de postura, y cuento por qué.', 3);

