insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('847e0019-3d73-4c69-b403-ba06521dd66b', 'trabajo', 'practica', 'Desde marzo',
   'La reunión empezó discutiendo el mes de agosto. Sofía pidió el gráfico completo y lo puso encima: «No es agosto. Hay una tendencia a la baja desde marzo». Nadie volvió a hablar de agosto. Esa tarde salieron con tres cosas que probar.',
   'Este mes ha ido flojo, ya remontará.', 'Hay una tendencia a la baja desde marzo.', 1),
  ('847e0019-3d73-4c69-b403-ba06521dd66b', 'familia', 'emocional', 'Se cocina menos',
   'Mi madre dice que en casa ya nadie cocina. No es verdad del todo, pero tampoco falso. «Hay una tendencia», le dije, «cada año un poco menos». Lo aceptó mejor así que como reproche. Ahora cocinamos los domingos, las dos juntas.',
   'Ya nadie cocina en esta casa.', 'Hay una tendencia: cada año un poco menos.', 2),
  ('847e0019-3d73-4c69-b403-ba06521dd66b', 'social', 'social', 'Cuatro años subiendo',
   'En la tienda del barrio discutían si los patinetes eran cosa de un verano. Sofía sacó las ventas de cuatro años. «Esto ya no es una moda», resumió, «es una tendencia, y no depende de la estación». Pidieron el doble para la temporada siguiente.',
   'Esto se lleva ahora, luego ya veremos.', 'Ya no es una moda, es una tendencia.', 3);

