insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4ebaf077-8da9-48d5-b4aa-933870a01616', 'trabajo', 'practica', 'El plazo del jueves',
   'El plazo se iba a aprobar por unanimidad cuando Ainara pidió un minuto. «Tiene una implicación que no hemos dicho: alguien trabaja el sábado». Se hizo el silencio. Aprobaron el plazo, pero con dos personas más y sin sábado.',
   'Eso luego trae cola, ya se verá.', 'Tiene una implicación que no hemos dicho.', 1),
  ('4ebaf077-8da9-48d5-b4aa-933870a01616', 'familia', 'emocional', 'El interés del tercer año',
   'Mi cuñado traía el préstamo casi firmado y muy contento con la cuota. Leímos el contrato en la cocina, con café. «La implicación está aquí», le señalé, «el interés sube en el tercer año». Volvió al banco y pidió otra cosa.',
   'Parece barato, ¿no?', 'La implicación está aquí: sube en el tercer año.', 2),
  ('4ebaf077-8da9-48d5-b4aa-933870a01616', 'social', 'social', 'Cerrar los sábados',
   'La asociación votaba cerrar el local los sábados. Beltrán no se opuso; solo puso una frase encima de la mesa: «La implicación es clara: todo se concentra el viernes». Decidieron cerrar igual, y contratar una mano más los viernes.',
   'Algo pasará el viernes, digo yo.', 'La implicación es clara: todo se concentra el viernes.', 3);

