insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('9253caa5-fb25-4113-b3c2-a206402c809f', 'trabajo', 'practica', 'Todo bien, salvo agosto',
   'El plan se votaba esa mañana y Lucas era el único que no había hablado. «Lo apruebo entero», dijo, «tengo un reparo con el plazo de agosto y ya está». Lo movieron dos semanas. El resto quedó exactamente igual.',
   'Hay una cosa que no me convence del todo.', 'Lo apruebo entero, tengo un reparo con el plazo.', 1),
  ('9253caa5-fb25-4113-b3c2-a206402c809f', 'familia', 'emocional', 'El contrato del piso',
   'Mi hermana leyó el contrato del piso dos veces, con un lápiz en la mano. Al final lo dejó sobre la mesa. «Lo firmo sin reparos», dijo, y firmó. Nunca la había visto tan tranquila con un papel.',
   'No le veo ningún problema, creo.', 'Lo firmo sin reparos.', 2),
  ('9253caa5-fb25-4113-b3c2-a206402c809f', 'social', 'social', 'La página tres',
   'El informe del local llegó sin propuestas y sin quejas: solo una línea en la página tres. «Es un reparo, no un no», explicó Isabel en la asamblea. Lo resolvieron en diez minutos y el resto se aprobó sin tocar nada.',
   'Le veo una pega, pero tampoco es para tanto.', 'Es un reparo, no un no.', 3);

