insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('fb6cbbcd-78d8-4bc1-9b63-1cb0f40cd4cc', 'trabajo', 'practica', 'La técnica y la otra',
   'Llevaban una hora discutiendo el mismo fallo sin avanzar. Amaya lo partió en dos: «Hay una vertiente técnica y otra de trato con el cliente. Empecemos por la segunda». La reunión duró quince minutos más y salieron con dos responsables, uno por cara.',
   'Es que aquí hay varias cosas mezcladas.', 'Hay una vertiente técnica y otra de trato.', 1),
  ('fb6cbbcd-78d8-4bc1-9b63-1cb0f40cd4cc', 'familia', 'emocional', 'El dinero y lo otro',
   'La mudanza de mi abuela se discutía siempre en números. Mi tía puso la otra cara sobre la mesa: «Está la vertiente del dinero y está la de dejar su calle». Esa noche hablamos por fin de lo segundo.',
   'También hay que mirarlo por lo humano.', 'Está la vertiente del dinero y está la otra.', 2),
  ('fb6cbbcd-78d8-4bc1-9b63-1cb0f40cd4cc', 'entrevista', 'practica', 'Un capítulo por cara',
   'Le pidieron a Amaya un ejemplo de informe suyo. Llevaba uno impreso. «Separé la vertiente económica de la legal y dediqué un capítulo a cada una», explicó. «Así nadie discute las dos a la vez». Se lo quedaron para enseñarlo dentro.',
   'Lo dividí un poco por temas.', 'Separé la vertiente económica de la legal.', 3);

