insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('8c7a05cc-3b15-49a3-96eb-c3cad9f481ee', 'trabajo', 'practica', 'Qué entra y qué no',
   'El encargo se había aprobado en dos minutos y en dos meses valía el doble de trabajo. La vez siguiente, Nicolás pidió otra cosa: «Escribamos el alcance antes de aprobar: qué entra y qué queda fuera». Media hora de más, tres semanas de menos.',
   'Ya iremos viendo hasta dónde llega.', 'Escribamos el alcance antes de aprobar.', 1),
  ('8c7a05cc-3b15-49a3-96eb-c3cad9f481ee', 'familia', 'emocional', 'Pintar una habitación',
   'Mi padre dijo que pintaría una habitación y acabó con la casa entera a medias. Este año lo dijimos claro desde el principio: «El alcance es el pasillo, nada más». Lo terminó un sábado y se sentó a leer, contento.',
   'Ya que estoy, sigo con lo demás.', 'El alcance es el pasillo, nada más.', 2),
  ('8c7a05cc-3b15-49a3-96eb-c3cad9f481ee', 'social', 'social', 'Cuatro delegaciones',
   'El cambio parecía una tontería: mover una firma de sitio en un formulario. Isabel lo miró dos veces. «Parece pequeño, pero su alcance toca a las cuatro delegaciones». Avisaron a todas antes de tocar nada y no hubo ni una llamada de vuelta.',
   'Es un cambio de nada, ¿no?', 'Parece pequeño, pero su alcance toca a las cuatro.', 3);

