insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('7c54e895-68e9-434f-9dc7-9492a3891f07', 'trabajo', 'practica', 'El ruido de la máquina',
   'La máquina nueva zumbaba desde el lunes. Nadie se quejaba, pero todos lo habían notado. «Es un zumbido leve», dijo Nacho en la reunión, «no molesta, pero antes no estaba». Vino el técnico el jueves y era una pieza suelta.',
   'Se oye algo raro, un poquito nada más.', 'Es un zumbido leve, pero antes no estaba.', 1),
  ('7c54e895-68e9-434f-9dc7-9492a3891f07', 'familia', 'emocional', 'Dos palabras y a comer',
   'Mi hermano se enfadó en la comida del domingo y casi no se le notó: una ceja, dos palabras y siguió comiendo. «Ha sido leve», comentó mi madre después, medio en broma. Al día siguiente lo hablaron y ya está.',
   'Se ha molestado un poco, tampoco tanto.', 'Ha sido leve, pero se ha molestado.', 2),
  ('7c54e895-68e9-434f-9dc7-9492a3891f07', 'social', 'social', 'Otra puntuación',
   'Dos versiones del cartel del barrio parecían idénticas. Una editora del grupo señaló la diferencia: el mismo texto con otra puntuación. «Es leve», reconoció, «y aun así una se lee y la otra no». Imprimieron la suya.',
   'Yo las veo iguales, cambia un poquito.', 'Es leve, y aun así una se lee y la otra no.', 3);

