insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('d3646890-6034-4616-a483-3d422419827b', 'trabajo', 'practica', 'El martes, no el miércoles',
   'Las entregas se habían movido tres veces y ya nadie se fiaba del calendario. Esta vez el correo traía una sola línea arriba: «Entrega el martes 14, no el miércoles». Fue inequívoco. No llamó nadie a preguntar.',
