insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('784b8706-1642-42fb-824c-d73da3427b7b', 'trabajo', 'practica', 'Dinero y trato',
   'En la lista de problemas iban todos juntos y la reunión saltaba de uno a otro. Adela los partió en dos columnas. «Son igual de serios, pero de distinta índole: estos son de dinero y estos de trato». Cada columna tuvo su reunión.',
   'Es que aquí hay problemas muy distintos.', 'Son de distinta índole: dinero y trato.', 1),
  ('784b8706-1642-42fb-824c-d73da3427b7b', 'familia', 'emocional', 'Otro tema',
   'Mi padre mezclaba la reforma del baño con lo del coche y acabábamos discutiendo por todo. Un día se lo dije con calma: «Lo del coche es un asunto de otra índole; hablémoslo mañana». Lo aceptó, y esa noche cerramos el baño.',
   'Eso ya es otro tema, papá.', 'Lo del coche es un asunto de otra índole.', 2),
  ('784b8706-1642-42fb-824c-d73da3427b7b', 'entrevista', 'practica', 'Preguntas del final',
   'Al final de la entrevista, Adela sacó dos preguntas de una libreta. «Una es de índole práctica, sobre horarios; la otra es sobre cómo se decide aquí». Las hizo por separado y recibió dos respuestas largas, no una corta.',
   'Tengo un par de dudas de cosas distintas.', 'Una es de índole práctica; la otra, no.', 3);

