insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('cde4f7d7-480d-4c97-9896-69492197bc28', 'trabajo', 'practica', 'Los tres minutos perdidos',
   'Elsa presentaba el proyecto por tercera vez y siempre pasaba igual: a los tres minutos la sala ya miraba el teléfono. Su compañero se lo dijo claro: «El contenido está bien; lo que falla es el arranque». Empezó por la cifra final y aquella vez nadie miró el teléfono.',
   'No sé por qué la gente se despista al principio.', 'Lo que falla es el arranque.', 1),
  ('cde4f7d7-480d-4c97-9896-69492197bc28', 'entrevista', 'practica', 'Veinte segundos',
   'Casimiro se preparaba la respuesta larga y descuidaba la primera frase. En la sexta entrevista cambió de método: escribió un arranque de veinte segundos y lo repitió en voz alta hasta que le salió solo. «Vengo de compras y quiero llevarlo a proveedores».',
   'Pues bueno, no sé muy bien por dónde empezar.', 'Llevo el arranque preparado.', 2),
  ('cde4f7d7-480d-4c97-9896-69492197bc28', 'social', 'social', 'El documental del sofá',
   'Marcela puso un documental sin muchas ganas y acabó viéndolo entero. «Es el arranque», le explicó luego a su vecina. «Los primeros dos minutos no te dejan levantarte». Su vecina lo puso esa misma noche y le pasó lo mismo.',
   'El principio está muy bien hecho.', 'Es el arranque: no te deja levantarte.', 3);

