insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('3375eae0-a1d8-4a7f-9fee-9b291bf95720', 'trabajo', 'practica', 'En el bolso, sin abrir',
   'Casandra escribió las frases de su presentación una a una y las repitió dos noches seguidas. El día señalado dejó los folios en el bolso y no los sacó. «Escribir el guion es lo que me lo deja en la cabeza», le contó después a su equipo. «Llevarlo encima ya es de más».',
   'Llevaba todo apuntado por si acaso.', 'Escribí el guion y luego no lo necesité.', 1),
  ('3375eae0-a1d8-4a7f-9fee-9b291bf95720', 'entrevista', 'practica', 'Los dos primeros minutos',
   'Ovidio llegaba a las entrevistas con todo aprendido palabra por palabra y salía con la boca seca. Cambió el método: guion cerrado para los dos primeros minutos y cuatro puntos para el resto. «Así arranco firme y después ya converso», explicó. En la tercera le dijeron que sí.',
   'Me lo aprendo entero y ojalá no se me olvide.', 'Llevo guion solo para los dos primeros minutos.', 2),
  ('3375eae0-a1d8-4a7f-9fee-9b291bf95720', 'social', 'emocional', 'La llamada difícil',
   'Ágata tenía que decirle a su casero que se mudaba y llevaba tres días posponiéndolo. Se escribió un guion de seis líneas y lo dejó al lado del teléfono. No lo leyó, pero llamó. Colgó a los cuatro minutos, aliviada.',
   'No sé ni cómo empezar esa llamada.', 'Me escribí un guion de seis líneas y llamé.', 3);

