insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('32fbcc57-cc65-4175-aa8c-1a17c951850b', 'trabajo', 'practica', 'Dos colores y una foto',
   'El equipo llevaba una semana discutiendo el folleto del taller. Beatriz llegó con una versión de dos colores, una foto y seis líneas. «Es demasiado sobrio», dijo alguien. Se imprimieron las dos y la gente cogió la suya: la otra se quedó en la caja.',
   'Este está muy simple, ¿no?', 'Este es sobrio, y por eso se lee.', 1),
  ('32fbcc57-cc65-4175-aa8c-1a17c951850b', 'familia', 'emocional', 'El traje de la boda',
   'Anselmo se probó siete trajes y volvió al primero. Su hermana le insistía con uno más llamativo. «Prefiero ir sobrio y que la gente mire a los novios», contestó. En las fotos de aquel día nadie se acordó de su traje, y él lo cuenta como una victoria.',
   'Yo voy sencillito, sin nada raro.', 'Prefiero ir sobrio.', 2),
  ('32fbcc57-cc65-4175-aa8c-1a17c951850b', 'social', 'social', 'La mesa de Olalla',
   'Olalla puso mantel blanco, una vela y nada más. Su vecina esperaba flores, servilletas dobladas y tres copas por persona. A media cena lo dijo en voz alta: «Qué bien se está aquí; es todo muy sobrio y se habla mejor». La conversación duró hasta la una.',
   'No he puesto nada del otro mundo.', 'Lo he puesto todo muy sobrio.', 3);

