insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('98d0bb3d-fc96-43ce-8328-d9da4eddc972', 'trabajo', 'practica', 'Dos minutos',
   'Eulalia tenía el último turno y quince diapositivas preparadas. Vio la hora, cerró el portátil y habló dos minutos: qué problema había, qué costaba y qué proponía. «Estuviste elocuente», le dijo después su jefa. «Y eso que no enseñaste ni una imagen».',
   'Creo que me expliqué bastante bien, ¿no?', 'Estuve elocuente sin enseñar una sola imagen.', 1),
  ('98d0bb3d-fc96-43ce-8328-d9da4eddc972', 'familia', 'emocional', 'El día del homenaje',
   'Nazaret nunca habla en las comidas de familia; se sienta al lado de la cocina y escucha. En el homenaje a su madre pidió un minuto y contó una escena de un verano. Cuando terminó, la sala estaba de pie. «Qué elocuente, tía», le dijo su sobrino.',
   'Qué bien lo has contado, de verdad.', 'Has estado elocuente.', 2),
  ('98d0bb3d-fc96-43ce-8328-d9da4eddc972', 'social', 'social', 'La carta de dos párrafos',
   'La comunidad llevaba meses discutiendo lo del patio. Celia escribió dos párrafos en el grupo: lo que costaba, lo que ganaban y una fecha. «Más elocuente que la reunión de hora y media», contestó un vecino. Se votó al día siguiente.',
   'Lo ha explicado en dos líneas y se entiende todo.', 'Dos párrafos más elocuentes que una reunión entera.', 3);

