insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('6912a9f6-cdea-453c-9754-5639f6cc12da', 'familia', 'emocional', 'El espejo de Berta',
   'Berta decía que sí a todas las comidas de los domingos y luego pasaba la semana enfadada. Una tarde ensayó delante del espejo: «Este domingo no puedo». Sin disculparse tres veces, sin inventar médicos. Su madre contestó «vale, la próxima» y ahí se acabó el asunto.',
   'Es que no sé decir que no sin quedar mal.', 'Ensayé mi negativa hasta que me salió corta.', 1),
  ('6912a9f6-cdea-453c-9754-5639f6cc12da', 'social', 'social', 'Dos noes y once síes',
   'En la reunión de la comunidad se votó arreglar el patio. Hubo dos negativas y once síes, y las dos personas que dijeron que no lo explicaron en un minuto. Nadie se levantó de la silla enfadado, y la obra empezó en octubre.',
   'Dos dijeron que no y ya está.', 'Hubo dos negativas, explicadas en un minuto.', 2),
  ('6912a9f6-cdea-453c-9754-5639f6cc12da', 'trabajo', 'practica', 'La carpeta de los noes',
   'Nerea guarda en una carpeta todas las respuestas que le dijeron que no. La primera es de hace nueve años. «Esa negativa me dio la lista de los otros doce sitios», cuenta. Al décimo tercero le dijeron que sí, y ese correo lo tiene enmarcado.',
   'Me dijeron que no y casi lo dejo.', 'Aquella negativa me dio la lista de los siguientes.', 3);

