insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('09867897-0593-4520-86d8-4a8b7ca824a5', 'familia', 'emocional', 'Tres fines de semana',
   'A Gaspar le pidieron ayuda para la tercera mudanza seguida. Estuvo a punto de decir que sí y luego se oyó a sí mismo suspirar. «Este no puedo; necesito un respiro». Su primo contestó con un audio de cuatro segundos: «Claro, hombre». Nadie se enfadó y el domingo durmió hasta las diez.',
   'Es que estoy reventado, pero bueno, voy.', 'Este no puedo: necesito un respiro.', 1),
  ('09867897-0593-4520-86d8-4a8b7ca824a5', 'social', 'social', 'La lluvia de octubre',
   'En el pueblo llevaban todo el verano hablando del agua. Cuando por fin llovió tres días seguidos, el vecino del huerto lo resumió en la puerta del bar: «Esto es un respiro, no la solución». Nadie discutió, pero esa tarde se quedaron todos mirando el cielo con mejor cara.',
   'Menos mal que por fin ha caído algo.', 'Esto es un respiro, no la solución.', 2),
  ('09867897-0593-4520-86d8-4a8b7ca824a5', 'trabajo', 'practica', 'Dos semanas y vuelvo',
   'Perla llevaba once meses sin una semana entera libre y empezaba a equivocarse en cosas tontas. Lo dijo así: «Pido un respiro de dos semanas y vuelvo». Su jefa movió una entrega y aceptó. Volvió el quince, con la cabeza clara y una lista de tres cosas que había que cambiar.',
   'No sé si aguanto mucho más así.', 'Pido un respiro de dos semanas y vuelvo.', 3);

