insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('76d1f97e-bc0b-4f96-bec8-53afa80ec27f', 'familia', 'emocional', 'La tarde de los jueves',
   'A Valentín le ofrecieron el turno de tarde con mejor horario de entrada. Hizo las cuentas y dijo que no: «Es incompatible con recoger a la niña los jueves». Su jefa le propuso los martes y aceptó. Nadie tuvo que hablar de ganas ni de esfuerzo.',
   'Es que no me cuadra con lo de la niña.', 'Es incompatible con recogerla los jueves.', 1),
  ('76d1f97e-bc0b-4f96-bec8-53afa80ec27f', 'social', 'social', 'Dos citas el jueves',
   'Ofelia había dicho que sí a dos cosas el mismo jueves a las siete. Al darse cuenta escribió a las dos personas la misma frase: «Son incompatibles, y prefiero avisar hoy». Movió una al viernes y llegó descansada a las dos.',
   'Uf, me he liado con las horas, qué desastre.', 'Las dos son incompatibles; muevo una.', 2),
  ('76d1f97e-bc0b-4f96-bec8-53afa80ec27f', 'trabajo', 'practica', 'Mayo no puede ser',
   'Federico vio el calendario del viaje y el de la mudanza y coincidían de lleno. Lo dijo el primer día, no la víspera: «Mayo me sale incompatible; junio entero lo tengo libre». El equipo movió el viaje a junio y nadie perdió un billete.',
   'A ver si puedo, aunque lo tengo complicado.', 'Mayo me sale incompatible; junio lo tengo libre.', 3);

