insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('42edbe89-8bd9-4bc7-8c95-580b4a5d08a2', 'social', 'social', 'La votación del portal',
   'En la reunión del portal se votaba cambiar el ascensor. Amadeo vive en el bajo y no lo usa nunca. «Me abstengo», dijo, «porque a mí no me afecta y a los demás sí». Nadie se lo tomó a mal y la obra salió adelante con diez votos.',
   'Yo paso, que a mí me da igual.', 'Me abstengo, porque a mí no me afecta.', 1),
  ('42edbe89-8bd9-4bc7-8c95-580b4a5d08a2', 'familia', 'emocional', 'El tema de la casa',
   'Cada vez que sale el tema de la casa del pueblo, Zoraida se levanta a por más café. No es que no tenga opinión: ha decidido abstenerse de darla mientras sus hermanos no se pongan de acuerdo. «Cuando se pongan de acuerdo, yo firmo lo que sea», dice.',
   'Yo de eso mejor no digo nada.', 'Prefiero abstenerme mientras no haya acuerdo.', 2),
  ('42edbe89-8bd9-4bc7-8c95-580b4a5d08a2', 'trabajo', 'practica', 'Trabajo con las dos partes',
   'A Aitana la invitaron a decidir entre dos proveedores con los que trabaja a diario. Contestó antes de la reunión: «Prefiero abstenerme en esta decisión; paso los datos de los dos y que decidan ellos». Le agradecieron los datos y la dejaron fuera de la votación.',
   'Es que yo aquí no debería opinar, ¿no?', 'Prefiero abstenerme en esta decisión.', 3);

