insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('7df846cc-348d-468a-832a-4ba96a410f86', 'familia', 'emocional', 'El cuarto verano',
   'Mireya pidió la misma ayuda tres veranos seguidos y tres veces se la negaron por un papel distinto. Al cuarto lo dijo en la comida, sin drama: «Este año desisto y me busco la vida de otra manera». Su hija le preguntó si estaba triste y ella dijo que no, que estaba libre.',
   'Nada, que lo dejo, ya me he cansado.', 'Este año desisto y busco otra vía.', 1),
  ('7df846cc-348d-468a-832a-4ba96a410f86', 'trabajo', 'practica', 'Cinco llamadas',
   'Adela llamó cinco veces al mismo proveedor y nadie cogió el teléfono. En vez de mandar un correo enfadado, escribió tres líneas al equipo: «Desisto con este; empiezo con los otros dos presupuestos». En diez días tenían material en el almacén.',
   'Nada, que estos pasan de mí.', 'Desisto con este y sigo con los otros dos.', 2),
  ('7df846cc-348d-468a-832a-4ba96a410f86', 'social', 'social', 'El año de la sequía',
   'En el huerto del barrio casi todos dejaron las parcelas el verano sin lluvia. Cayetano no desistió: acarreó agua en garrafas y sombreó los tomates con cañas. En septiembre repartió dos cajas por el portal y nadie le dejó pagar el café ese mes.',
   'Yo seguí a lo mío y ya está.', 'No desistí, aunque casi todos lo dejaron.', 3);

