insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('848a4ace-7bc5-4d8b-ad5c-55285940102e', 'entrevista', 'practica', 'Tres, no diecisiete',
   'Mario llegaba a las entrevistas con diecisiete puestos que contar y salía con la sensación de no haber dicho nada. Cambió el método: eligió tres hitos y explicó qué cambió después de cada uno. La conversación pasó de veinte minutos a cincuenta, y esa vez le llamaron.',
   'Te cuento todo lo que he ido haciendo.', 'Te cuento tres hitos y qué cambió después de cada uno.', 1),
  ('848a4ace-7bc5-4d8b-ad5c-55285940102e', 'familia', 'emocional', 'El carné a los cuarenta',
   'Inés se sacó el carné a los cuarenta y dos, después de tres intentos. En casa lo cuentan como el hito de aquella década, por encima de cualquier cosa del trabajo. Desde entonces, los domingos conduce ella y elige la música sin discusión.',
   'Fue muy importante para mí, de verdad.', 'Fue el hito de aquella década.', 2),
  ('848a4ace-7bc5-4d8b-ad5c-55285940102e', 'trabajo', 'practica', 'Cuatro puntos en el plan',
