insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('2d908774-5d20-49a8-b7bd-02ec52cbc8a5', 'entrevista', 'practica', 'Dos frases y un lío',
   'A Sonia le preguntaron por su mayor fortaleza y no dijo «trabajar en equipo». Dijo: «Ordenar un lío que ya empezó», y contó el mes en que se cayó un proveedor a tres semanas de la entrega. La entrevistadora dejó de mirar el papel y le preguntó cómo lo hizo.',
   'Pues se me dan bien bastantes cosas, la verdad.', 'Mi mayor fortaleza es ordenar un lío que ya empezó.', 1),
  ('2d908774-5d20-49a8-b7bd-02ec52cbc8a5', 'trabajo', 'practica', 'El reparto de octubre',
   'En octubre el equipo repartió el trabajo de otra manera: cada uno apuntó dos fortalezas suyas en la pizarra y eligieron por ahí. Nadie acabó con lo mismo que el año anterior. Iris se quedó con la parte que exigía paciencia, y fue la única que no se quejó.',
   'Que cada uno coja lo que se le dé bien.', 'Repartimos según las fortalezas de cada uno.', 2),
  ('2d908774-5d20-49a8-b7bd-02ec52cbc8a5', 'familia', 'emocional', 'Lo que dijo su hija',
   'Lola se quejaba en la cena de que no tenía nada que contar en una entrevista. Su hija, de quince años, lo dijo sin levantar la vista del plato: «Tu fortaleza es que la gente te cuenta cosas». Lola lo apuntó en el móvil y lo usó dos días después.',
   'Yo es que no destaco en nada, hija.', 'Tu fortaleza es que la gente te cuenta cosas.', 3);

