insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('b1d843ce-064f-4701-8e0c-0307a2e969b7', 'trabajo', 'practica', 'Diez segundos',
   'El cliente felicitó al equipo por haber encontrado el fallo. Encarna esperó a que terminara el aplauso y dijo una frase: «El mérito es de Sandra, que revisó los ficheros antiguos un sábado». Sandra se puso roja, y desde entonces cuenta lo que hace sin que nadie se lo pida.',
   'Bueno, lo hicimos entre todos.', 'El mérito es de Sandra, que revisó los ficheros.', 1),
  ('b1d843ce-064f-4701-8e0c-0307a2e969b7', 'familia', 'emocional', 'A los sesenta',
   'Aurelio corrió su primera carrera larga a los sesenta y dos años y llegó el penúltimo. Su nieto le enseñó el tiempo en el móvil, con cara de disculpa. Aurelio se rio: «El mérito no lo mide ese reloj». La foto de la llegada está en el pasillo de casa.',
   'Bueno, llegar ya es algo, ¿no?', 'El mérito no lo mide ese reloj.', 2),
  ('b1d843ce-064f-4701-8e0c-0307a2e969b7', 'social', 'social', 'Entre seis',
   'En el portal dicen que la mudanza de Manuela la organizó ella sola. Manuela lo corrige cada vez que sale el tema: «El mérito fue de los seis que subieron cajas; yo abrí la puerta y puse café». La versión corregida ya la cuenta hasta el portero.',
   'Qué va, yo no hice casi nada.', 'El mérito fue de los seis que subieron cajas.', 3);

