insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4e312688-9fea-467f-bcb8-d8349911175f', 'trabajo', 'practica', 'El grifo del barrio',
   'El equipo llevaba media hora perdido en porcentajes. Milena se levantó: «Va una analogía: la red es un grifo y cada casa tiene su turno; si uno abre el suyo entero, los demás se quedan secos». Tres personas dijeron «ah» a la vez y la reunión avanzó.',
   'A ver, es como si… no sé cómo explicarlo.', 'Va una analogía y lo vemos claro.', 1),
  ('4e312688-9fea-467f-bcb8-d8349911175f', 'familia', 'social', 'El chocolate prestado',
   'Su hija quería saber por qué el banco cobra por prestar dinero. Gaspar pensó un momento. «Esta analogía te va a servir: tú le prestas chocolate a tu hermano y él te devuelve un poco más porque lo tuvo una semana». Ella asintió y preguntó cuánto más.',
   'Es complicado, ya lo entenderás de mayor.', 'Esta analogía te va a servir.', 2),
  ('4e312688-9fea-467f-bcb8-d8349911175f', 'social', 'emocional', 'La bañera',
   'Jimena contaba que ahorraba y ahorraba sin que la cuenta subiera. Su amigo la escuchó hasta el final. «La analogía que a mí me sirvió: es una bañera con el tapón quitado; no llenas más, tapas mejor». Jimena se quedó callada un rato, y luego sacó el móvil para mirar sus cobros.',
   'No sé, es como que se me escapa el dinero.', 'La analogía que a mí me sirvió es una bañera.', 3);

