insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('5419049f-deff-4fcf-a32b-e79afd5c3ebf', 'trabajo', 'practica', 'Dame dos semanas',
   'El responsable preguntó si ya manejaba la herramienta nueva. Renzo no dijo que sí por quedar bien. «La entiendo, todavía no la asimilo. Dame dos semanas y te la explico yo a ti». Las tuvo, y al final del mes formaba a los que entraban.',
   'Sí, sí, más o menos ya me hago con ello.', 'La entiendo, todavía no la asimilo.', 1),
  ('5419049f-deff-4fcf-a32b-e79afd5c3ebf', 'familia', 'emocional', 'La casa del pueblo',
   'Vendieron la casa en marzo y su hermana no volvió a nombrarla. En agosto, de pronto, contó una historia de aquel verano y se rio. «Creo que por fin lo asimilé», dijo. Nadie añadió nada; la conversación siguió sola.',
   'Ya me voy haciendo a la idea, supongo.', 'Creo que por fin lo asimilé.', 2),
  ('5419049f-deff-4fcf-a32b-e79afd5c3ebf', 'social', 'social', 'Café de los jueves',
   'Cintia llevaba un mes en el club de lectura y hablaba poco. El jueves interrumpió dos veces. «Perdón, es que ya asimilé cómo funciona esto y quiero discutirlo todo». El grupo se rio y le guardaron el turno.',
   'Ya me voy enterando de cómo va esto.', 'Ya asimilé cómo funciona esto.', 3);

