insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('451677fc-47de-4e72-8559-b01c0fe493c8', 'trabajo', 'practica', 'Contesto el jueves',
   'El correo llegó a las siete de la tarde y era injusto. Milena empezó tres respuestas y borró las tres. Al final escribió otra cosa: «Te contesto el jueves con sosiego». El jueves su respuesta cabía en seis líneas y nadie salió herido.',
   'Ahora mismo estoy demasiado caliente para contestar.', 'Te contesto el jueves con sosiego.', 1),
  ('451677fc-47de-4e72-8559-b01c0fe493c8', 'familia', 'emocional', 'Media hora',
   'Su hermano llegó de la reunión con los puños cerrados. Antes de que nadie preguntara, dijo: «Necesito media hora de sosiego y lo cuento todo». Nadie insistió. A los treinta minutos salió a la cocina y lo contó entero, sin levantar la voz.',
   'Necesito un rato a solas, que ahora no puedo.', 'Media hora de sosiego y lo cuento todo.', 2),
  ('451677fc-47de-4e72-8559-b01c0fe493c8', 'social', 'social', 'El turno de palabra',
   'En la asamblea todos hablaban a la vez. Casandra levantó la mano y esperó. Cuando el ruido bajó, dijo: «Ahora que hay sosiego, lo digo en dos frases». Las dijo, y fue lo único que quedó anotado en el acta.',
   'A ver si nos calmamos todos un poco.', 'Ahora que hay sosiego, lo digo en dos frases.', 3);

