insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4fbceaf4-fde6-4a64-90f1-302273f17199', 'trabajo', 'practica', 'El modo, no el fondo',
   'Los turnos nuevos aparecieron un lunes en el tablón. En la reunión, Vera lo dijo sin levantar la voz: «El horario me parece bien; lo que no me parece bien es la imposición». Al mes siguiente hubo una reunión antes de colgar nada.',
   'Es que aquí nunca nos preguntan nada.', 'El horario está bien; la imposición, no.', 1),
  ('4fbceaf4-fde6-4a64-90f1-302273f17199', 'familia', 'emocional', 'Lo llamó consejo',
   'Su padre le explicó qué debía estudiar y en qué ciudad. Casandra no discutió esa tarde, pero tardó dos meses en volver a contarle nada. Al final se lo dijo: «Tú lo llamaste consejo y a mí me llegó como imposición».',
   'Me dijiste lo que tenía que hacer y ya.', 'Lo llamaste consejo; me llegó como imposición.', 2),
  ('4fbceaf4-fde6-4a64-90f1-302273f17199', 'social', 'social', 'El menú del domingo',
   'En casa de Gaspar cada uno propone un plato y se vota. Un invitado preguntó si no era mucho lío. «Prefiero el lío a la imposición», contestó él. Aquel domingo hubo dos primeros platos y nadie se levantó de la mesa.',
   'Aquí no manda nadie con la comida.', 'Prefiero el lío a la imposición.', 3);

