insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('6bfcccaa-f710-4134-ae2a-7a36d053276c', 'trabajo', 'practica', 'Con «por favor»',
   'El correo terminaba con un «por favor» y aun así nadie se atrevió a contestar. Vera lo nombró en la reunión: «Esto es una exigencia disfrazada; si de verdad es negociable, que se diga». Reescribieron el correo y dos personas propusieron otra fecha.',
   'Nos lo pidieron de muy malas maneras.', 'Esto es una exigencia, aunque lleve «por favor».', 1),
  ('6bfcccaa-f710-4134-ae2a-7a36d053276c', 'familia', 'emocional', 'Antes de las dos',
   'La comida de los domingos empezaba siempre con la misma frase de su suegra. Un día, Tomás lo dijo con calma: «Para nosotros es una exigencia, y nos gustaría que fuera una petición». Comieron a las dos y cuarto y no pasó nada.',
   'Es que siempre nos obliga a llegar pronto.', 'Para nosotros es una exigencia, no una petición.', 2),
  ('6bfcccaa-f710-4134-ae2a-7a36d053276c', 'entrevista', 'practica', 'Las del puesto',
   'Le preguntaron si podía estar disponible los fines de semana. Vera no dijo que sí sin más: «¿Es una exigencia del puesto o algo excepcional? Según la respuesta, mi respuesta cambia». Se lo aclararon, y firmó sabiendo dónde entraba.',
   '¿Eso es obligatorio o cómo va?', '¿Es una exigencia del puesto o algo excepcional?', 3);

