insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('3db622e3-5a62-4887-93fc-6bf032a0ad97', 'trabajo', 'practica', 'La nota a mano',
   'El departamento recibía veinte correos automáticos al día. Aquella mañana llegó un sobre con una nota escrita a mano. «Es un ruego, no una reclamación», empezaba. Tres personas la leyeron en voz alta y la petición se atendió esa semana.',
   'Pido por favor, si es posible, que…', 'Es un ruego, no una reclamación.', 1),
  ('3db622e3-5a62-4887-93fc-6bf032a0ad97', 'familia', 'emocional', 'Un ruego, no una orden',
   'Su hijo mayor ya no vive en casa y viene cuando puede. Su madre dejó de insistir y cambió la forma: «Esto es un ruego, no una orden: avísame si no vienes». Él empezó a avisar, y las comidas dejaron de enfriarse.',
   'Podrías avisar, ¿no te parece?', 'Esto es un ruego, no una orden.', 2),
  ('3db622e3-5a62-4887-93fc-6bf032a0ad97', 'social', 'social', 'El buzón del vecino',
   'El coche del segundo bloqueaba la salida cada mañana. Yago no llamó al timbre ni escribió al grupo del edificio. Dejó una nota corta en el buzón, firmada. «Era un ruego y funcionó», contó luego. El coche apareció aparcado al otro lado.',
   'Le puse una nota pidiéndole el favor.', 'Era un ruego, y funcionó.', 3);

