insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('1a442784-327d-457f-b824-b106edca565c', 'trabajo', 'practica', 'El primer turno',
   'Los tres nuevos llegaron un lunes y nadie se levantó de la silla. Vera lo cambió al mes siguiente: preparó una hoja con nombres y los presentó uno a uno. «Aceptarlos no basta; hay que acogerlos», dijo. El siguiente equipo se integró en una semana.',
   'Hay que integrarlos mejor, hacerles más caso.', 'Aceptarlos no basta: hay que acogerlos.', 1),
  ('1a442784-327d-457f-b824-b106edca565c', 'familia', 'emocional', 'Dos maletas',
   'Su prima apareció un domingo con dos maletas y sin explicación. Nadie preguntó nada esa noche. «En esta casa primero se acoge y luego, si quieres, cuentas», le dijo su tía. Contó la historia entera tres días después.',
   'Pasa, pasa, ya nos contarás qué ha pasado.', 'Primero se acoge y luego, si quieres, cuentas.', 2),
  ('1a442784-327d-457f-b824-b106edca565c', 'social', 'social', 'La biblioteca nueva',
   'Abrieron la biblioteca en marzo y en junio ya era el punto de encuentro del barrio. Nadie organizó nada: la gente entró, se sentó y volvió. «El barrio la ha acogido», resumió la bibliotecaria, y siguió colocando libros.',
   'A la gente le ha gustado mucho, se ve.', 'El barrio la ha acogido.', 3);

