insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('74484ed1-5018-466c-ad7f-35b9259c18d7', 'familia', 'emocional', 'El piso de abajo',
   'Después de once años, se mudó al piso de abajo del mismo bloque. Nadie entendía nada. «El cariño está intacto; lo que se rompió fue la convivencia», explicó en la comida del domingo. Siguen cenando juntos los martes.',
   'Nos queremos, pero juntos no podemos.', 'El cariño está intacto; se rompió la convivencia.', 1),
  ('74484ed1-5018-466c-ad7f-35b9259c18d7', 'trabajo', 'practica', 'Dos mesas, una oficina',
   'Los socios llevaban meses hablándose por correo estando a tres metros. Un asesor externo lo nombró en la primera sesión: «Las cuentas están bien; el problema es la convivencia». Cambiaron el reparto de responsabilidades y volvieron a comer juntos.',
   'Es que no nos soportamos y así no se puede.', 'Las cuentas están bien; el problema es la convivencia.', 2),
  ('74484ed1-5018-466c-ad7f-35b9259c18d7', 'social', 'social', 'Siete y media',
   'Tres personas y un baño: cada mañana era una negociación de miradas. Un domingo hicieron un cuadro con horas y duchas. «La convivencia se arregla con detalles tontos», resumió una de ellas. Nadie volvió a discutir por el agua caliente.',
   'Es que vivir juntos es un lío constante.', 'La convivencia se arregla con detalles tontos.', 3);

