insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('32134204-c54c-4f48-9017-48e6f61d8db5', 'social', 'social', 'Diez minutos de lluvia',
   'Se cortó la luz en plena cena y quedaron seis personas con dos velas. Marina levantó el vaso y dijo: «Qué acierto haber elegido el restaurante más moderno de la ciudad». Todos se rieron, incluida la dueña. La ironía sirvió de puente: en diez minutos ya nadie hablaba de la luz.',
   'Lo dije al revés, medio en broma.', 'Lo dije con ironía.', 1),
  ('32134204-c54c-4f48-9017-48e6f61d8db5', 'familia', 'emocional', 'El cuarto de Tobías',
   'Su madre abrió la puerta, vio la ropa por el suelo y dijo: «Impecable, como siempre». Tobías se rio y empezó a recoger sin discutir. Después le contó que en el trabajo llevaba dos semanas sin dormir bien. La ironía le había ahorrado la regañina y le había abierto la conversación.',
   'Podría haberle gritado por el desorden.', 'Una ironía suave y se abrió solo.', 2),
  ('32134204-c54c-4f48-9017-48e6f61d8db5', 'trabajo', 'practica', 'El correo que no se envía',
   'Norma escribió «gracias por avisar con tanto tiempo» y se quedó mirando la frase. Recordó que su compañera no conocía su tono y que, por escrito, la ironía viaja mal. Borró la línea y escribió: «Avísame antes la próxima vez, por favor». La respuesta llegó en dos minutos y con una disculpa.',
   'Lo escribí al revés y quedó raro.', 'La ironía funciona hablando, no por escrito.', 3);

