insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('2ae0743f-4dc8-4d36-bb85-597fcd6e821c', 'social', 'social', 'El video de los perritos',
   'En medio de la primera cita, a Rita se le aguaron los ojos viendo un video que le mandó su hermana. «Perdón, me da mucha ternura cualquier cosa con animales», le dijo a su acompañante entre risas. Él solo sonrió: «No te disculpes, me parece lo más lindo que he visto en esta cita».',
   'Perdón, soy muy sensible con estas cosas.', 'Me da mucha ternura cualquier cosa con animales.', 1),
  ('2ae0743f-4dc8-4d36-bb85-597fcd6e821c', 'familia', 'emocional', 'La receta de la abuela',
   'Cuando Vidal vio a su padre intentar hacer la receta de su abuela sin encontrar la parte correcta en la libreta vieja, sintió una ternura que no esperaba. Se sentó a su lado y le ayudó a descifrarla, sin decir nada más.',
   'Me dio no sé qué verlo así, con la libreta.', 'Sentí una ternura que no esperaba.', 2),
  ('2ae0743f-4dc8-4d36-bb85-597fcd6e821c', 'trabajo', 'practica', 'El compañero nuevo',
   'En su primer día, el compañero nuevo no encontraba la impresora y preguntó tres veces sin atreverse a levantar la voz. A Casilda le dio tanta ternura verlo tan perdido que lo acompañó personalmente a cada rincón de la oficina.',
   'Me dio no sé qué verlo tan perdido.', 'Me dio tanta ternura verlo tan perdido que lo ayudé.', 3);

