insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('9b50d80c-5a98-45a4-ad66-43c31ba9bab4', 'social', 'social', 'La cuenta regresiva',
   'Faltaban tres días para la cita y Bautista ya había revisado el menú del restaurante dos veces. Se lo contó a su compañero de piso, medio avergonzado. «No te rías, pero me hace mucha ilusión», le dijo. Su compañero sonrió: «Se nota, llevas toda la semana de buen humor».',
   'Estoy como loco esperando que llegue el sábado.', 'Me hace mucha ilusión esta cita.', 1),
  ('9b50d80c-5a98-45a4-ad66-43c31ba9bab4', 'familia', 'emocional', 'La llamada a mi madre',
   'Jimena llamó a su madre después de la primera cita, todavía con la sonrisa puesta. «Me hizo mucha ilusión, mamá, hacía tiempo que no me pasaba», le contó. Su madre se rio: «Se te nota en la voz, hija; cuéntamelo todo».',
   'Estoy feliz, hacía tiempo que no me pasaba.', 'Me hizo mucha ilusión, hacía tiempo que no me pasaba.', 2),
  ('9b50d80c-5a98-45a4-ad66-43c31ba9bab4', 'trabajo', 'practica', 'El comentario en la pausa',
   'En la pausa del café, Damián le contó a una compañera que tenía una segunda cita esa noche. «Se me nota la ilusión, ¿verdad?», le preguntó, un poco nervioso. Ella se rio: «Un poco, sí, pero te queda bien».',
   'Se me nota que estoy contento, ¿no?', 'Se me nota la ilusión, ¿verdad?', 3);

