insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('a22db4a5-213b-491d-8287-75648a9ce35d', 'social', 'social', 'El perfil sin fotos',
   'En la fiesta, alguien le mencionó a Tadeo que había un chico nuevo con un perfil sin ninguna foto y solo una frase: «Pregúntame en persona». Tadeo se pasó la noche buscando una excusa para acercarse. «Me da tanta intriga esa frase», le confesó a su amigo, sin dejar de mirar hacia la puerta.',
   'Qué curiosidad me da esa persona, no sé por qué.', 'Me da tanta intriga esa frase.', 1),
  ('a22db4a5-213b-491d-8287-75648a9ce35d', 'familia', 'emocional', 'El comentario de mi hermana',
   'Dante le contó a su hermana que su cita había mencionado una ciudad donde vivió, sin decir por qué se fue. «Eso me da intriga», le dijo, «pero no quiero preguntar directo y que se sienta interrogado». Su hermana se rio: «Pregúntale con calma, no es un interrogatorio».',
   'Tengo mucha curiosidad, pero no quiero preguntar directo.', 'Eso me da intriga, pero no quiero que se sienta interrogado.', 2),
  ('a22db4a5-213b-491d-8287-75648a9ce35d', 'trabajo', 'practica', 'La pausa del café',
   'En la pausa del café, Aitana le contó a un compañero que su cita del fin de semana casi nunca hablaba de su familia. «Me da intriga por qué evita el tema», comentó, todavía pensando en ello. Su compañero solo levantó una ceja: «A lo mejor simplemente no le gusta hablar de eso».',
   'Me da curiosidad por qué nunca habla de su familia.', 'Me da intriga por qué evita el tema.', 3);

