insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('a36d248d-ceb3-41a7-9b0d-9da994b67066', 'social', 'social', 'El mensaje que no llega',
   'Después de la primera cita, Ezequiel no dejaba de mirar el teléfono, aunque sin ansiedad. «Tengo un anhelo tranquilo de que me escriba», le contó a un amigo, «sé que lo va a hacer, solo estoy esperando con ganas».',
   'Tengo muchas ganas de que me escriba, aunque sin desesperarme.', 'Tengo un anhelo tranquilo de que me escriba.', 1),
  ('a36d248d-ceb3-41a7-9b0d-9da994b67066', 'familia', 'emocional', 'La conversación con mi madre',
   'Malena le contó a su madre que, desde que había conocido a alguien especial, sentía unas ganas constantes de compartir su día a día con esa persona. «Eso es un anhelo bonito», le dijo su madre, «disfrútalo, no hace falta que corras».',
   'Tengo ganas de compartir mi vida con esa persona, sin prisa.', 'Eso es un anhelo bonito, dice mi madre.', 2),
  ('a36d248d-ceb3-41a7-9b0d-9da994b67066', 'trabajo', 'practica', 'El comentario en el almuerzo',
   'En el almuerzo, Aitana le contó a una compañera que llevaba semanas con ganas de volver a ver a alguien que había conocido en un viaje, sin ninguna prisa por que pasara pronto. «Eso es puro anhelo», comentó su compañera, sonriendo, «qué bonito sentirlo así de tranquilo».',
   'Tengo ganas de volver a verlo, sin ninguna prisa.', 'Eso es puro anhelo, tan tranquilo.', 3);

