insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4a81c065-3aa5-4208-8889-c3d68257b769', 'social', 'social', 'El mismo vuelo',
   'Fabiola y Tobías se conocieron porque a los dos les cambiaron la puerta de embarque a último momento y terminaron sentados juntos en la sala de espera. Fue un encuentro fortuito: ninguno de los dos había elegido esa fila de asientos. Hoy se siguen escribiendo cada semana.',
   'Nos conocimos de pura casualidad.', 'Fue un encuentro fortuito, y seguimos hablando.', 1),
  ('4a81c065-3aa5-4208-8889-c3d68257b769', 'familia', 'emocional', 'La foto encontrada',
   'Buscando un cargador en el cajón de la abuela, Renzo encontró una foto de ella de joven que nadie había visto. Fue un hallazgo fortuito, pero bastó para que la abuela contara historias toda la sobremesa que nunca antes había compartido.',
   'La encontré de casualidad, buscando otra cosa.', 'Fue un hallazgo fortuito, y abrió una tarde entera de historias.', 2),
  ('4a81c065-3aa5-4208-8889-c3d68257b769', 'trabajo', 'practica', 'El café equivocado',
   'Bárbara tomó por error el café de otra persona en la sala común. El dueño, en vez de molestarse, se rio y se presentó. Fue un cruce fortuito, pero terminaron trabajando juntos en un proyecto meses después.',
   'Fue pura casualidad que habláramos.', 'Fue un cruce fortuito, y terminamos trabajando juntos.', 3);

