insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('574f4a76-6e14-4a4f-83a3-c47fc2990917', 'trabajo', 'practica', 'El escritorio compartido',
   'Rogelio siempre dejaba papeles y tazas sobre el escritorio que compartía con Eduardo. Un día, un nuevo compañero le preguntó a Eduardo si eso no le molestaba. «Tengo indulgencia con eso», respondió, «al final, él siempre encuentra todo, y nunca me deja sin espacio». El nuevo compañero se quedó pensando en su propio escritorio.',
   'No me importa que sea un poco desordenado, la verdad.', 'Tengo indulgencia con eso, al final nunca me deja sin espacio.', 1),
  ('574f4a76-6e14-4a4f-83a3-c47fc2990917', 'familia', 'emocional', 'Los nombres confundidos',
   'Wilfredo llevaba años confundiendo los nombres de sus primos en cada reunión, y siempre entre risas. Una prima nueva le preguntó a la tía si eso no cansaba. «Con Wilfredo tenemos mucha indulgencia», dijo la tía, «total, se los sabe a la tercera vez que los saluda». La prima se rio y le enseñó su nombre otra vez.',
   'Ya nos acostumbramos, no le decimos nada.', 'Con Wilfredo tenemos mucha indulgencia, se los sabe a la tercera.', 2),
  ('574f4a76-6e14-4a4f-83a3-c47fc2990917', 'social', 'social', 'El café de los quince minutos',
   'Paulina llegó tarde otra vez al café de los sábados. Nadie dijo nada, como siempre. Una amiga nueva del grupo preguntó si eso no molestaba a nadie. «Con Paulina tenemos toda la indulgencia del mundo», le explicó una de ellas, «siempre llega, solo que a su ritmo». La amiga nueva se relajó y pidió otro café mientras esperaban.',
   'Ya sabemos cómo es, no le decimos nada por llegar tarde.', 'Con Paulina tenemos toda la indulgencia del mundo.', 3);

