insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('82c950e8-645c-4bc2-a077-ec767a15b791', 'familia', 'emocional', 'El pueblo de la abuela',
   'Cada verano, Camila visitaba el pueblo donde había crecido su abuela, aunque ella nunca había vivido ahí. Un día, caminando por la plaza, saludó a tres personas que la reconocieron sin que ella las recordara. Ahí entendió que sentía pertenencia con ese lugar, aunque nunca hubiera vivido en él.',
   'No sé por qué, pero aquí me siento en casa.', 'Siento pertenencia con este lugar.', 1),
  ('82c950e8-645c-4bc2-a077-ec767a15b791', 'social', 'social', 'El grupo de corredores',
   'Valeria empezó a correr sola por el parque, hasta que un grupo la invitó a unirse. Al principio se sentía fuera de lugar, pero después de unas semanas ya la esperaban si faltaba un día. «Ya siento pertenencia con ustedes», les dijo un domingo, y todos brindaron con agua después de la carrera.',
   'Todavía me siento un poco fuera de lugar aquí.', 'Ya siento pertenencia con este grupo.', 2),
  ('82c950e8-645c-4bc2-a077-ec767a15b791', 'trabajo', 'practica', 'El primer proyecto propio',
   'Durante meses, Rodrigo sintió que solo ejecutaba las ideas de otros. Cuando por fin lideró su primer proyecto de principio a fin, algo cambió: empezó a sentir pertenencia con la empresa, no solo con su sueldo. Se lo contó a su pareja esa misma noche, orgulloso.',
   'Siento que este lugar por fin es mío también.', 'Siento pertenencia con la empresa, no solo un sueldo.', 3);

