insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('c1e439bd-c832-484b-9737-871ab258b54e', 'familia', 'emocional', 'Diez años que valieron la pena',
   'Perla se sentó junto a la cama del hospital sin dormir, otra vez. Cuando su hijo por fin dio los primeros pasos solo por el pasillo, ella se echó a llorar de alivio. «Todos esos desvelos valieron la pena», le dijo a su marido esa noche, ya con la luz apagada.',
   'Tantas noches sin dormir por él valieron la pena.', 'Todos esos desvelos valieron la pena.', 1),
  ('c1e439bd-c832-484b-9737-871ab258b54e', 'social', 'social', 'Sobremesa de abuelas',
   'En la sobremesa, la abuela de Camilo contaba sus desvelos de hace treinta años como si fueran de ayer: la fiebre de una noche, el llanto de otra. Las demás abuelas asentían, cada una con su propia historia. Nadie se quejaba: hablaban de eso con una sonrisa.',
   'Me acuerdo de esas noches sin dormir como si fuera ayer.', 'Me acuerdo de esos desvelos como si fuera ayer.', 2),
  ('c1e439bd-c832-484b-9737-871ab258b54e', 'trabajo', 'practica', 'El café de las siete',
   'Marisol llegó a la oficina con el segundo café antes de las ocho. «Entre entregas de trabajo y pañales, mis desvelos esta semana no se los quita nadie», le dijo a su jefe, medio en broma. Él le ofreció mover una reunión para que pudiera dormir una hora más al día siguiente.',
   'No he dormido nada esta semana entre los niños y las entregas de trabajo.', 'Mis desvelos esta semana no se los quita nadie.', 3);

