insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('399a1360-f02a-4913-b0db-d1afd4acf466', 'social', 'social', 'La sobremesa que no acababa',
   'Nadie quería levantarse de la mesa mientras Tomás seguía hablando. Contaba el viaje en tren con tanta viveza —las voces, las pausas, el final inesperado— que hasta quien ya lo había escuchado antes volvió a reírse. «Cuéntalo otra vez», le pidieron, y él no se hizo de rogar.',
   'Cuenta las cosas muy bien, hace reír a todos.', 'Cuenta las cosas con mucha viveza.', 1),
  ('399a1360-f02a-4913-b0db-d1afd4acf466', 'trabajo', 'practica', 'El informe que sí se leyó',
   'El jefe pidió un resumen del trimestre y esperaba diez minutos de números. Nuria lo presentó con tanta viveza que la sala se rió dos veces antes de llegar a la última diapositiva. «Así sí se entienden las cifras», dijo alguien al salir.',
   'Lo explica muy bien y no aburre a nadie.', 'Lo explica con mucha viveza.', 2),
  ('399a1360-f02a-4913-b0db-d1afd4acf466', 'familia', 'emocional', 'La historia de siempre',
   'Cada Navidad, el tío contaba la misma anécdota del asado quemado, y cada año sonaba distinta. La abuela decía que era su viveza la que la hacía nueva cada vez, aunque los detalles fueran los mismos de siempre. Este año, hasta el primo más pequeño se quedó a escucharla completa.',
   'Cuenta lo mismo de siempre, pero de una forma que engancha.', 'Lo cuenta con una viveza que engancha.', 3);

