insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('dd8e80d5-39c1-41f8-bb38-b8a23843a1bc', 'social', 'social', 'El anfitrión inesperado',
   'Nadie esperaba que Martín, tan reservado en el trabajo, tuviera tanta gracia contando historias. En la fiesta de fin de año, terminó rodeado de gente pidiéndole «una más». Su compañera de equipo lo miraba sin poder creerlo: era otra persona con un micrófono improvisado en la mano.',
   'Es muy simpático cuando cuenta cosas.', 'Tiene mucha gracia contando cosas.', 1),
  ('dd8e80d5-39c1-41f8-bb38-b8a23843a1bc', 'familia', 'emocional', 'La historia del auto averiado',
   'Cada Año Nuevo, el tío Emilio cuenta cómo se quedó varado en la ruta con el auto humeando. La historia es la misma desde hace diez años, pero la gracia con la que la cuenta cambia cada vez un detalle, y la familia entera vuelve a reírse como la primera vez.',
   'Cuenta lo mismo de siempre, pero suena distinto cada vez.', 'Lo cuenta con una gracia que nunca se gasta.', 2),
  ('dd8e80d5-39c1-41f8-bb38-b8a23843a1bc', 'trabajo', 'practica', 'El aviso que nadie ignoró',
   'El administrador del edificio pidió cerrar bien la puerta del garaje, un aviso que normalmente nadie lee. Bruno lo redactó con tanta gracia, comparando la puerta con un portero dormido, que hasta los vecinos más quejosos lo comentaron en el chat con risas.',
   'Lo explicó de un modo que cayó bien a todos.', 'Lo explicó con mucha gracia.', 3);

