insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('e472dbd9-b08f-4f30-a514-f02f0073db78', 'social', 'social', 'El grupo que no calla',
   'En el chat de amigos alguien mandó una foto seria de su primer día de trabajo. Joaquín contestó con una tontería sobre el café de la oficina que no tenía nada que ver, y en minutos el chat entero se llenó de risas y memes. Nadie recordaba ya el motivo original del mensaje.',
   'Dije algo random sin venir a cuento.', 'Solté una tontería sin venir a cuento.', 1),
  ('e472dbd9-b08f-4f30-a514-f02f0073db78', 'familia', 'emocional', 'La cena que se salvó',
   'La cena había empezado tensa, con un silencio incómodo entre hermanos. Valentina, sin planearlo, soltó una tontería sobre el perro tratando de abrir el refrigerador, y la risa de todos rompió el silencio. Nadie volvió a mencionar el tema pendiente esa noche.',
   'Dije algo random para cambiar el ambiente.', 'Solté una tontería para cambiar el ambiente.', 2),
  ('e472dbd9-b08f-4f30-a514-f02f0073db78', 'trabajo', 'practica', 'El aviso que se hizo viral',
   'El aviso sobre la cafetera rota llevaba semanas sin que nadie lo leyera. Emiliano lo reescribió con una tontería sobre una cafetera «en huelga», y por primera vez todos comentaron el mensaje en el grupo de la oficina. El aviso se arregló el mismo día.',
   'Escribí algo gracioso sin venir a cuento para que lo lean.', 'Escribí una tontería para que por fin lo lean.', 3);

