insert into public.exercise_options (exercise_id, text, is_correct, distractor_type, why_not, hint_specific, position)
select exercise.id, o.text, o.is_correct, o.distractor_type, o.why_not, o.hint_specific, o.position
from exercise
cross join (values
    ('extensa', false, 'near_synonym', '«Extensa» solo dice que el texto es largo, y lo que hizo que se compartiera tanto fue su filo, no su extensión.', '«Extensa» habla de longitud. ¿La compartieron por ser larga o por tener filo?', 1),
