insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('239df552-b1a7-4fb2-967d-21e0a5c2c087', 'familia', 'emocional', 'El pavo de cada Navidad',
   'Cada Nochebuena, la tía Noelia jura que este año el pavo le va a quedar perfecto, y cada año se le quema un poco por un lado. Ya nadie se sorprende: bromean con ella desde que empieza a servir la cena, y ella misma se ríe primero que nadie.',
   'Nos reímos con ella del pavo quemado, año tras año.', 'Bromeamos con ella del pavo quemado, año tras año.', 1),
  ('239df552-b1a7-4fb2-967d-21e0a5c2c087', 'trabajo', 'practica', 'El chat antes de la reunión difícil',
   'El equipo sabía que la reunión con el cliente iba a ser tensa. Diez minutos antes, alguien mandó un meme al chat y todos empezaron a bromear sobre el peor escenario posible. Cuando entraron a la llamada, la tensión había bajado varios grados.',
   'Nos reímos un rato en el chat para relajarnos antes de la reunión.', 'Bromeamos un rato en el chat para relajarnos antes de la reunión.', 2),
  ('239df552-b1a7-4fb2-967d-21e0a5c2c087', 'social', 'social', 'Las citas de la semana',
   'Las amigas se juntaron a cenar y, como cada viernes, terminaron hablando de las citas que habían tenido. Bromearon durante horas sobre las señales de alarma más ridículas que habían visto esa semana, y ninguna se tomó nada demasiado en serio.',
   'Nos reímos toda la noche de las citas, sin ponernos serias.', 'Bromeamos toda la noche sobre las citas, sin ponernos serias.', 3);

