insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('c9277950-58e3-4a14-bd07-8f4b80b43bff', 'familia', 'emocional', 'El comentario torpe',
   'En la cena, el hermano de Antonia soltó un comentario torpe sobre su nuevo trabajo. Ella lo miró, pero enseguida pensó en lo nervioso que había estado esa semana. «Lo excuso, sé que no lo dijo con mala intención», le dijo después a su madre. La cena siguió sin más roces.',
   'No pasa nada, ya sé que no quiso decir eso.', 'Lo excuso, sé que no lo dijo con mala intención.', 1),
  ('c9277950-58e3-4a14-bd07-8f4b80b43bff', 'social', 'social', 'La tardanza de Marcos',
   'Marcos llegó veinte minutos tarde a la reunión de amigos, con el pelo mojado y sin aliento. «El bus se rompió a dos cuadras, vine corriendo», explicó. Verónica sonrió: «Te excuso, con esa cara de susto no hace falta que jures nada». El grupo siguió la noche como si nada.',
   'Tranquilo, entiendo que se te complicó.', 'Te excuso, no hace falta que expliques más.', 2),
  ('c9277950-58e3-4a14-bd07-8f4b80b43bff', 'trabajo', 'practica', 'El correo de las tres de la mañana',
   'Ricardo leyó dos veces el correo de Lorena antes de responder: estaba lleno de errores y frases a medias. Pero recordó que ella había mandado ese mensaje camino al aeropuerto, después de un vuelo cancelado. «La excuso, cualquiera escribe así con esa noche», pensó, y respondió sin comentar nada sobre la redacción.',
   'No le voy a decir nada, tuvo una noche horrible.', 'La excuso, cualquiera escribe así con esa noche.', 3);

