insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('7b0013dc-ddcf-4521-9783-b4ddd1516951', 'trabajo', 'practica', 'El informe sin firmar',
   'El contrato llevaba tres semanas en la bandeja. Marisol no repartió culpas: preguntó en voz alta, mirando al papel. «¿Piensa firmarlo acaso alguien esta semana?». Dos personas se miraron y el contrato salió firmado esa misma tarde.',
   '¿Nadie lo firma o qué?', '¿Piensa firmarlo acaso alguien esta semana?', 1),
  ('7b0013dc-ddcf-4521-9783-b4ddd1516951', 'familia', 'emocional', 'Domingo otra vez',
   'Ulises llevaba meses recordando lo mismo cada semana. En vez de levantar la voz, dejó el teléfono boca abajo y preguntó: «¿Hace falta acaso repetirlo cada domingo?». Su hijo se quedó callado, y esta vez sacó la basura sin que nadie insistiera.',
   'Otra vez lo mismo, ¿te lo tengo que decir mil veces?', '¿Hace falta acaso repetirlo cada domingo?', 2),
  ('7b0013dc-ddcf-4521-9783-b4ddd1516951', 'social', 'social', 'El paraguas de Nagore',
   'Salieron a pasear con el cielo cargado. Nagore volvió a entrar a por el paraguas y lo dijo sin dramas: «Me lo llevo por si acaso». Media hora después, cuatro personas caminaban debajo de él y nadie se atrevió a reírse.',
   'Me lo llevo, tú por si las moscas.', 'Me lo llevo por si acaso.', 3);

