insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('22f9f96d-9e05-4baf-a294-9404ed3b97a1', 'trabajo', 'practica', 'Dos líneas y el archivo',
   'El correo de Leonor cabía en la pantalla: «Aquí tienes el cierre del mes. Adjunto el detalle por si quieres revisarlo». Su jefa respondió en cinco minutos, algo que casi nunca pasaba. «Así da gusto», escribió.',
   'Ahí te paso el archivo.', 'Adjunto el detalle.', 1),
  ('22f9f96d-9e05-4baf-a294-9404ed3b97a1', 'familia', 'emocional', 'Las fotos del viaje',
   'Su padre llevaba semanas preguntando por las fotos. Tadeo dejó de prometerlas y escribió: «Adjunto las diez mejores; el resto va el domingo». Media hora después su padre ya las había impreso y las tenía en la mesa.',
   'Un día de estos te las mando.', 'Adjunto las diez mejores.', 2),
  ('22f9f96d-9e05-4baf-a294-9404ed3b97a1', 'entrevista', 'practica', 'El correo después de la charla',
   'Al salir de la entrevista, Nadia escribió tres líneas de agradecimiento y añadió: «Adjunto el caso del que hablamos, con las cifras del primer año». La entrevistadora lo abrió esa misma tarde y lo compartió con su equipo.',
   'Si quieres te mando luego el caso ese.', 'Adjunto el caso del que hablamos.', 3);

