insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('e6119105-c9ef-4a32-9ae1-36c677380134', 'trabajo', 'practica', 'La cena con el cliente nuevo',
   'Antes de la cena, el gerente le dijo a Sofía: «Tú eres la anfitriona esta noche». Sofía llegó temprano, revisó la mesa y preparó dos preguntas para cada invitado. Cuando el cliente se fue, dijo que era la mejor cena de trabajo del año.',
   'Yo me encargo de que todos estén cómodos.', 'Esta noche soy la anfitriona.', 1),
  ('e6119105-c9ef-4a32-9ae1-36c677380134', 'social', 'social', 'La casa siempre abierta',
   'Cada domingo, Tomás recibía a quien quisiera pasar. «Eres un anfitrión nato», le dijo un amigo nuevo, sorprendido de que se acordara de su nombre y de que no comía picante. Tomás solo sonrió: llevaba años practicando eso.',
   'Siempre te acuerdas de todo lo de tus invitados.', 'Eres un anfitrión nato.', 2),
  ('e6119105-c9ef-4a32-9ae1-36c677380134', 'familia', 'emocional', 'La primera Navidad en su casa',
   'Era la primera vez que Elena recibía a toda la familia en su casa nueva. Su madre la vio moverse entre las mesas, presentando a los primos que no se conocían. «Ya eres la anfitriona de esta familia», le dijo al oído, y Elena sintió que por fin tenía su lugar.',
   'Ahora yo organizo la Navidad.', 'Ahora yo soy la anfitriona de esta familia.', 3);

