insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('bf655a65-933d-47aa-b227-924467b43aeb', 'trabajo', 'practica', 'La mesa de madera',
   'En la feria había un puesto con pantallas y otro con una mesa de madera. El primero deslumbraba y el segundo vendió el triple. Casilda lo apuntó en su libreta esa noche: «Deslumbrar entretiene; explicar vende».',
   'Aquel puesto impresionaba muchísimo.', 'Aquel puesto deslumbraba y no vendía.', 1),
  ('bf655a65-933d-47aa-b227-924467b43aeb', 'familia', 'emocional', 'La foto del piso',
   'Mi hermano firmó el alquiler por una foto con luz de tarde. La humedad de la cocina estaba ahí, esperándolo. «Me dejé deslumbrar», reconoció meses después, sin dramatizar. Ahora visita los pisos por la mañana.',
   'Me dejé llevar por lo bonita que era.', 'Me dejé deslumbrar.', 2),
  ('bf655a65-933d-47aa-b227-924467b43aeb', 'entrevista', 'practica', 'Tres segundos',
   'Le preguntaron a Vera cómo hacía vídeos que la gente terminaba. «Los tres primeros segundos tienen que deslumbrar», contestó, «y del cuarto en adelante tiene que haber algo que valga». La segunda parte de la frase fue la que apuntaron todos.',
   'Al principio hay que impactar.', 'Los tres primeros segundos tienen que deslumbrar.', 3);

