insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('5d964576-dfeb-4ade-afbd-52e808c8982a', 'entrevista', 'practica', 'El terreno más cómodo',
   'El periodista insistió en preguntar por el despido. Tomás no lo negó ni lo escondió: reconoció el hecho en una frase y desvió la respuesta hacia lo que había aprendido después. «Aprendí a pedir ayuda antes de que un problema crezca», cerró, y el periodista pasó a la siguiente pregunta.',
   'Mejor cambio de tema, esto no me conviene.', 'Desvié la respuesta hacia lo que aprendí.', 1),
  ('5d964576-dfeb-4ade-afbd-52e808c8982a', 'familia', 'social', 'El partido del sábado',
   'Apenas se sentaron a cenar, la madre preguntó por las notas. El niño contestó con una frase corta y enseguida desvió la charla hacia el partido del sábado. Ella se dio cuenta, sonrió y dejó pasar el tema hasta después del postre.',
   'Mejor hablamos de otra cosa, esto se puso feo.', 'Desvié la charla hacia el partido.', 2),
  ('5d964576-dfeb-4ade-afbd-52e808c8982a', 'trabajo', 'practica', 'La cláusula difícil',
   'El contrato tenía una cláusula que a nadie le gustaba. En vez de detenerse ahí, el abogado desvió la atención hacia las ventajas generales del acuerdo y volvió a la cláusula al final, cuando ya había confianza. «Prefiero mostrar el conjunto antes que un solo punto», explicó su equipo después.',
   'Mejor resalto lo bueno antes de entrar en eso.', 'Desvié la atención hacia las ventajas generales.', 3);

