insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('b225b7d7-06e3-4b77-8f85-dbbd115bed9f', 'trabajo', 'practica', 'La cita del notario',
   'El equipo llevaba media hora atascado en la ronda y nadie quería decirlo. Genaro llamó y avisó sin dramatizar: «Con este tráfico difícilmente llegamos a las ocho». El notario movió la cita veinte minutos y la firma salió igual.',
   'No creo que lleguemos, con este tráfico, no sé.', 'Con este tráfico difícilmente llegamos a las ocho.', 1),
  ('b225b7d7-06e3-4b77-8f85-dbbd115bed9f', 'social', 'social', 'El pan del mercado viejo',
   'Le preguntaron por qué cruzaba media ciudad para comprar pan. Rosenda lo dijo sin presumir: «Un pan así difícilmente se encuentra en otro sitio». Tres personas de la mesa apuntaron la dirección en el teléfono.',
   'Es que un pan así no lo encuentras en ningún lado, o sea.', 'Un pan así difícilmente se encuentra en otro sitio.', 2),
  ('b225b7d7-06e3-4b77-8f85-dbbd115bed9f', 'familia', 'emocional', 'La mesa de agosto',
   'Nadie se atrevía a preguntar si habría comida familiar después de la bronca de mayo. Su tía lo dijo con calma y sin cerrar la puerta: «Difícilmente compartirán mesa este verano». Justo por decirlo así, en septiembre alguien se atrevió a llamar.',
   'Ni de broma se sientan juntos, tú verás.', 'Difícilmente compartirán mesa este verano.', 3);

