insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('014af208-9747-42f7-b988-28bb9518ddf2', 'familia', 'emocional', 'El comentario que dolió',
   'Rubén supo apenas lo dijo que había ido demasiado lejos. Esa noche llamó a su hermana: «Me disculpo por el comentario, no tenía derecho a decir eso», le dijo, sin agregar ningún pero. Ella se quedó callada un momento, y después le agradeció la llamada.',
   'Perdón por lo que dije, no tenía derecho.', 'Me disculpo por lo que dije, no tenía derecho.', 1),
  ('014af208-9747-42f7-b988-28bb9518ddf2', 'trabajo', 'practica', 'El retraso de la entrega',
   'En vez de armar una lista de razones, la gerenta fue directa en el correo: «Nos disculpamos por el retraso, la responsabilidad es nuestra». El cliente respondió en minutos, sorprendido de no tener que insistir para escuchar eso.',
   'Reconocemos que la responsabilidad es nuestra.', 'Nos disculpamos, la responsabilidad es nuestra.', 2),
  ('014af208-9747-42f7-b988-28bb9518ddf2', 'social', 'social', 'Los dos días de silencio',
   'Ninguno quería dar el primer paso después de la discusión. Al tercer día, Camila lo llamó: «Me quiero disculpar, dije cosas que no pensaba de verdad». Su amigo respiró aliviado: llevaba dos días esperando esa llamada.',
   'Quiero pedirte perdón, dije cosas que no pensaba.', 'Me quiero disculpar, dije cosas que no pensaba.', 3);

