insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('77f7d914-45d6-46ca-b21a-f578c621706e', 'trabajo', 'practica', 'El taller de al lado',
   'Los tiempos de entrega no bajaban por más turnos que añadieran. Ignacio propuso otra cosa: «Vamos a emular el método del taller de la avenida, tal cual, un mes». En cuatro semanas recortaron dos días.',
   'Hagámoslo como ellos, a ver si funciona.', 'Vamos a emular su método un mes.', 1),
  ('77f7d914-45d6-46ca-b21a-f578c621706e', 'entrevista', 'practica', 'A quién te pareces',
   'Le preguntaron a Sara por su forma de dirigir. Contestó sin rodeos: «Trato de emular a mi primera jefa: escuchaba entera la frase antes de responder». Le pidieron un ejemplo concreto y lo tenía preparado.',
   'Intento hacerlo como lo hacía mi primera jefa.', 'Trato de emular a mi primera jefa.', 2),
  ('77f7d914-45d6-46ca-b21a-f578c621706e', 'familia', 'emocional', 'El pan de los domingos',
   'La panadería de la esquina cerró y en casa nadie se resignaba. Cecilia se puso con la receta cada domingo durante un año. «No pretendo emularlo del todo», decía, «pero cada vez se parece más».',
   'A ver si me sale igual que el suyo.', 'No pretendo emularlo del todo.', 3);

