insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('99eeb879-6b8d-4570-a878-4cc66662a599', 'social', 'social', 'El desconocido de la terraza',
   'En la terraza de la boda, Sofía se sentó junto a un primo del novio al que nunca había visto. Antes del brindis ya se reía con él como si lo conociera de años. «Qué tipo tan encantador», le dijo a su amiga esa noche, todavía sorprendida de lo rápido que había pasado.',
   'Cae buenísimo desde que lo conoces.', 'Qué tipo tan encantador.', 1),
  ('99eeb879-6b8d-4570-a878-4cc66662a599', 'trabajo', 'practica', 'La nueva del equipo',
   'El primer día de Renata en la oficina, se presentó a cada persona por su nombre y preguntó por sus proyectos como si ya los conociera. Al final del día, alguien comentó en el chat del equipo: «Es encantadora, ya quiero que se quede con nosotros».',
   'Es súper agradable desde que la conoces.', 'Es encantadora, ya quiero que se quede con nosotros.', 2),
  ('99eeb879-6b8d-4570-a878-4cc66662a599', 'familia', 'emocional', 'La novia que Diego trajo a casa',
   'Diego llevó a su novia a la comida familiar por primera vez, y en menos de una hora ella ya sabía el nombre de cada sobrino. Al despedirse, su madre le susurró: «Es encantadora, tráela más seguido».',
   'Cae buenísima con toda la familia, qué rápido.', 'Es encantadora, tráela más seguido.', 3);

