insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('df50b5ea-409a-4584-b7c2-93ff9e8353a7', 'trabajo', 'practica', 'Cuatro días sin servidor',
   'La avería no se arreglaba hasta el jueves y el equipo estaba parado mirando la pantalla. Zaida escribió tres líneas al grupo: «El técnico llega el jueves; entretanto, trabajamos con el equipo de repuesto». Nadie volvió a preguntar qué hacer.',
   'Pues nada, hasta el jueves y mientras ya veremos.', 'El técnico llega el jueves; entretanto, usamos el de repuesto.', 1),
  ('df50b5ea-409a-4584-b7c2-93ff9e8353a7', 'familia', 'emocional', 'La cita de octubre',
   'La espera se le hacía larga y su madre lo notaba en cada llamada. Olalla lo dijo sin queja: «Me dieron cita para octubre; entretanto, busco algo más cerca de casa». Su madre respiró: por fin había un plan, no solo una fecha lejana.',
   'Hasta octubre nada, y mientras pues nada.', 'Me dieron cita para octubre; entretanto, busco algo más cerca.', 2),
  ('df50b5ea-409a-4584-b7c2-93ff9e8353a7', 'social', 'social', 'Media hora de horno',
   'Llegaron los seis a la vez y el horno estaba frío. Baltasar repartió la espera en una frase: «Tarda media hora; entretanto, ponemos la mesa y abrimos el vino». La cocina se llenó de gente con algo que hacer y la noche empezó antes que la cena.',
   'Tarda media hora, así que mientras, pues eso.', 'Tarda media hora; entretanto, ponemos la mesa.', 3);

