insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('6438b4fc-474f-4ed5-9870-73951c16fd07', 'trabajo', 'practica', 'Olor a cartón',
   'Otilia tenía que explicar por qué el almacén nuevo cambiaba todo y la sala estaba dormida. Empezó así: «¿Recuerdas el olor a cartón mojado del sótano viejo?». Tres personas hicieron una mueca. Con eso evocó el problema mejor que con cualquier gráfico.',
   'El almacén antiguo tenía humedad, ya lo sabes.', '¿Recuerdas el olor a cartón mojado?', 1),
  ('6438b4fc-474f-4ed5-9870-73951c16fd07', 'familia', 'emocional', 'El tren de las siete',
   'Ivo y su hermano no hablaban de aquel invierno desde hacía años. Bastó una frase en la cena: «El tren de las siete». Los dos se rieron a la vez. Evocó un año entero sin contar una sola escena.',
   '¿Te acuerdas de aquella época, cuando íbamos en tren y tal?', 'El tren de las siete: con eso lo evoco todo.', 2),
  ('6438b4fc-474f-4ed5-9870-73951c16fd07', 'social', 'social', 'La canción de la mesa pequeña',
   'En la fiesta de los diez años, Gonzalo no dio un discurso. Puso una canción de aquellos primeros meses y dijo dos frases. La sala entera sonrió a la vez: la canción evocó el local diminuto donde habían empezado.',
   'Quería recordarte cómo empezamos, bla, bla.', 'Esta canción evoca la mesa donde empezamos.', 3);

