insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('80820fd9-ff36-4e40-bff0-5136d4b3bc0d', 'trabajo', 'practica', 'Las sillas de la boda',
   'Terminada la boda quedaron cuarenta sillas apiladas y nadie sabía qué hacer con ellas. Vera lo resolvió en una frase: «Con el excedente montamos la sala pequeña». Al día siguiente la sala estaba lista y aún sobraban seis.',
   'Nos sobraron un montón de sillas.', 'Con el excedente montamos la sala pequeña.', 1),
  ('80820fd9-ff36-4e40-bff0-5136d4b3bc0d', 'familia', 'emocional', 'Las botellas de mi abuelo',
   'Mi abuelo hacía conserva para un batallón. Cuando le preguntábamos por qué tanta, contestaba: «El excedente es lo que se llevan los nietos en Navidad». Ahora entiendo que cocinaba de más a propósito.',
   'Siempre le sobraba muchísimo.', 'El excedente es lo que se llevan los nietos.', 2),
  ('80820fd9-ff36-4e40-bff0-5136d4b3bc0d', 'entrevista', 'practica', 'No bajar el ritmo',
   'Le preguntaron a Salvador qué hizo cuando la fábrica produjo de más. «No bajamos el ritmo», dijo. «Colocamos el excedente en dos ciudades vecinas y nadie perdió turnos». Le pidieron los números y los llevaba encima.',
   'Nos sobraba producto y lo colocamos por ahí.', 'Colocamos el excedente en dos ciudades vecinas.', 3);

