insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('a8387a0a-a5b8-4ab2-94f0-64cbef9eb8e2', 'trabajo', 'practica', 'De tres a nueve',
   'En la reunión con el cliente nadie entendía por qué el equipo pedía más espacio. Baudilio lo contó en una frase: «Inicialmente éramos tres; hoy somos nueve». El cliente miró los planos de la sala y aprobó la mudanza de planta esa misma tarde.',
   'Es que al principio éramos tres, y claro, ahora pues nueve.', 'Inicialmente éramos tres; hoy somos nueve.', 1),
  ('a8387a0a-a5b8-4ab2-94f0-64cbef9eb8e2', 'familia', 'emocional', 'El barrio nuevo',
   'Se había resistido un año entero a dejar la casa de siempre. Cuando su hijo le preguntó si estaba a gusto, Encarnación lo reconoció sin drama: «Inicialmente no quería mudarme, y ahora no me iría de aquí». Su hijo guardó la frase para la próxima discusión.',
   'Al principio no quería, ya sabes, pero bueno.', 'Inicialmente no quería mudarme, y ahora no me iría de aquí.', 2),
  ('a8387a0a-a5b8-4ab2-94f0-64cbef9eb8e2', 'entrevista', 'practica', 'El local de los sábados',
   'Le pidieron que explicara cómo había crecido su negocio sin hacerlo largo. Aniceto respondió con dos datos y una palabra que ordenaba los dos: «Inicialmente abríamos solo los fines de semana». Después contó el resto en menos de un minuto.',
   'Al principio abríamos solo los findes, o sea, poquito.', 'Inicialmente abríamos solo los fines de semana.', 3);

