insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('f0218b15-734d-44be-bca8-88d510374d7d', 'trabajo', 'practica', 'Antes del correo',
   'Circulaban rumores sobre la reorganización. En vez de alimentarlos, Álvaro habló claro en la reunión: «El anuncio es inminente. Cuando llegue, lo leemos juntos y decidimos qué cambia para nosotros». La sala se calmó en un minuto.',
   'Dicen que va a salir en cualquier momento.', 'El anuncio es inminente.', 1),
  ('f0218b15-734d-44be-bca8-88d510374d7d', 'familia', 'emocional', 'La caja de la abuela',
   'La mudanza de su madre era al día siguiente y Beatriz seguía sin abrir la caja de fotos. Su hermano se sentó al lado: «El camión es inminente, pero esta caja la abrimos hoy, con calma». Tardaron dos horas y valió la pena.',
   'Ya casi está encima lo del camión.', 'El camión es inminente.', 2),
  ('f0218b15-734d-44be-bca8-88d510374d7d', 'social', 'social', 'Sillas fuera',
   'En la terraza nadie miraba el cielo. Renata se levantó y empezó a apilar sillas: «La tormenta es inminente, os lo digo yo». Cinco minutos después llovía y el grupo seguía cenando, seco, dentro de la casa.',
   'Va a caer de un momento a otro.', 'La tormenta es inminente.', 3);

