insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('838013ff-fb45-46c5-a6a4-d74138b9348c', 'trabajo', 'practica', 'El protocolo nuevo',
   'Antes de abrir el turno, el gerente reunió a todo el equipo. «Nadie sale a la sala sin saber qué hacer si suena la alarma», dijo, y empezó a instruirlos sobre el protocolo paso a paso. Cuando terminó, hasta la persona más nueva del equipo repitió los pasos sin dudar.',
   'Le expliqué a todos qué hacer, paso a paso.', 'Instruí a todos sobre el protocolo, paso a paso.', 1),
  ('838013ff-fb45-46c5-a6a4-d74138b9348c', 'familia', 'emocional', 'La receta de los domingos',
   'Cada domingo, mi abuela me llamaba a la cocina antes que a nadie más. «Esto no se aprende mirando, se aprende con las manos», decía mientras me instruía sobre la masa de los tamales. Nunca escribió la receta en papel: prefirió pasármela así, un domingo tras otro.',
