insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('d1ac25a2-6ae0-43a1-93a2-cdca20cd614e', 'social', 'social', 'El vecino más callado',
   'Después de la operación de su padre, Marina no esperaba que su vecino más reservado le preguntara nada. «Me interesé por saber cómo sigue, espero que esté mejor», le dijo un día en el ascensor, y esas pocas palabras la ayudaron más de lo que él imaginaba.',
   'Quería saber cómo sigue tu padre de verdad.', 'Me interesé por saber cómo sigue tu padre.', 1),
  ('d1ac25a2-6ae0-43a1-93a2-cdca20cd614e', 'familia', 'emocional', 'El tío después de tanto tiempo',
   'Llevaban años sin hablar más que en las fiestas de fin de año. Esta vez, su tío se sentó a su lado y le preguntó por sus estudios con calma. «Nunca pensé que te interesarías tanto por mi carrera», le dijo, sorprendido.',
   'Nunca pensé que preguntarías tanto por mi carrera.', 'Nunca pensé que te interesarías tanto por mi carrera.', 2),
  ('d1ac25a2-6ae0-43a1-93a2-cdca20cd614e', 'trabajo', 'practica', 'Antes de los resultados',
   'Antes de repasar los números del trimestre, la directora se tomó cinco minutos para preguntar por la familia de cada uno. «Me gusta interesarme por ustedes antes de hablar de números», dijo, y el ambiente de la reunión cambió por completo.',
   'Me gusta preguntar por la gente antes de hablar de números.', 'Me gusta interesarme por la gente antes de hablar de números.', 3);

