insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('ddfa9b72-866f-4e6c-b901-95ba431cb472', 'trabajo', 'practica', 'El primer párrafo',
   'Zoe escribe titulares que no prometen milagros. «Quiero intrigar, no engañar», explicó en la reunión. Su regla es sencilla: la pregunta que abre el título se contesta en el primer párrafo. Es la que menos clics pierde a mitad de texto.',
   'Quiero que entren, pero sin engañar.', 'Quiero intrigar, no engañar.', 1),
  ('ddfa9b72-866f-4e6c-b901-95ba431cb472', 'social', 'social', 'El plato de comida',
   'A mi abuela le intrigaba la vecina nueva del cuarto, así que subió con un plato y llamó a la puerta. Volvió dos horas después con la historia entera y una receta apuntada. Su método no ha fallado en cuarenta años.',
   'Me daba curiosidad esa vecina.', 'Me intrigaba esa vecina.', 2),
  ('ddfa9b72-866f-4e6c-b901-95ba431cb472', 'entrevista', 'practica', 'La pregunta del principio',
   'Vera abrió la charla con una pregunta y no la contestó hasta el último minuto. «Si intrigo al principio, me escuchan al final», dijo luego. Nadie se levantó antes de tiempo, y eso en una sala de cien personas es una proeza.',
   'Les dejo con la duda para que aguanten.', 'Si intrigo al principio, me escuchan al final.', 3);

