insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4d230f81-638c-4708-8268-df8b89149507', 'trabajo', 'practica', 'Una sola palabra',
   'El cartel anterior tenía cinco colores y nadie lo miraba. Efraín lo cambió por una palabra negra sobre fondo blanco. «Llamativo no es ruidoso», explicó. Aquella semana entró el doble de gente al taller.',
   'Que se vea mucho, con colores.', 'Llamativo no es ruidoso.', 1),
  ('4d230f81-638c-4708-8268-df8b89149507', 'entrevista', 'practica', 'La página en blanco',
   'Le pidieron a Nerea un detalle que le hubiera cambiado una reunión. Contó el del informe: nadie comentó las cifras y todos mencionaron una página en blanco entre dos capítulos. «Era lo más llamativo del documento y no decía nada», explicó. «Ahora reviso la maqueta antes que los números».',
   'Lo que más se ve es esa página vacía.', 'Es lo más llamativo del documento.', 2),
  ('4d230f81-638c-4708-8268-df8b89149507', 'familia', 'social', 'La camisa de la boda',
   'Mi tío apareció en la boda con una camisa que se veía desde el aparcamiento. Salió en todas las fotos, y en la mitad se estaba riendo. «Era llamativa y lo sabía», dijo al día siguiente. Nadie discutió ninguna de las dos cosas.',
   'Esa camisa se veía un montón.', 'Era llamativa y él lo sabía.', 3);

