insert into public.exercise_options (exercise_id, text, is_correct, distractor_type, why_not, hint_specific, position)
select exercise.id, o.text, o.is_correct, o.distractor_type, o.why_not, o.hint_specific, o.position
from exercise
cross join (values
    ('maniobrar', false, 'paronym', '«Maniobrar» es mover algo con habilidad, como un vehículo o una situación táctica, y aquí se acusa de alterar el contenido de un video.', '«Maniobrar» se usa con vehículos o situaciones tácticas. ¿De qué acusan al director: de moverse con habilidad o de alterar un video?', 1),
    ('manipular', true, null, null, null, 2),
    ('convencer', false, 'near_synonym', '«Convencer» es lograr que alguien cambie de opinión con argumentos a la vista, y aquí la acusación es que se alteró el video mismo, no que se debatiera con nadie.', '«Convencer» usa argumentos abiertos. ¿La acusación habla de un debate o de un video alterado?', 3)
) as o (text, is_correct, distractor_type, why_not, hint_specific, position);

