insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('e4149111-b1c1-4338-8c89-e8ce7f3b1161', 'entrevista', 'practica', 'El video del inicio',
   'El periodista puso el video completo junto al recorte que circulaba. «Aquí se ve que cortaron los primeros minutos», dijo, «eso es manipular la imagen de lo que pasó». El director no supo qué responder.',
   'Están cortando el video para que parezca otra cosa.', 'Eso es manipular la imagen de lo que pasó.', 1),
  ('e4149111-b1c1-4338-8c89-e8ce7f3b1161', 'trabajo', 'practica', 'El acta que faltaba',
   'Wilfredo comparó su copia del acta con la que circuló después de la reunión. Faltaba justo el párrafo sobre el retraso de Anabel. «No se te olvidó por accidente», le dijo, «manipulaste el documento para que tu error no quedara escrito».',
   'Cambiaste el documento para que no se notara tu error.', 'Manipulaste el documento para que tu error no quedara escrito.', 2),
  ('e4149111-b1c1-4338-8c89-e8ce7f3b1161', 'familia', 'emocional', 'La versión del viaje',
   'Cada vez que alguien contaba el viaje, la versión de su padre cambiaba un poco. Leonor lo notó por fin: «Papá, sé que manipulas la historia para que parezca que todos decidimos, y en realidad fuiste tú solo». Él se quedó callado un momento y luego sonrió, medio avergonzado.',
   'Estás cambiando la historia para quedar bien.', 'Sé que manipulas la historia para quedar bien con todos.', 3);

