insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('5aba881f-5daf-4c41-9297-95891ff51c91', 'social', 'social', 'Treinta segundos',
   'En la feria todos decían su cargo y su empresa. Gael dijo un ejemplo de dos frases y se calló. Al día siguiente le habían escrito cuatro personas. «No busco caer bien», nos explicó, «busco ser memorable una sola vez».',
   'A ver si se acuerdan de mí.', 'Busco ser memorable una sola vez.', 1),
  ('5aba881f-5daf-4c41-9297-95891ff51c91', 'familia', 'emocional', 'La historia del tren',
   'Mi abuelo contaba siempre la misma historia del tren y nadie lo interrumpía. Ahora la cuenta mi madre, con las mismas pausas. Es la única historia memorable de la familia, y no porque fuera la mejor: porque él la contó cien veces.',
   'Esa historia no se nos olvida.', 'Es la única historia memorable de la familia.', 2),
  ('5aba881f-5daf-4c41-9297-95891ff51c91', 'trabajo', 'practica', 'Una sola imagen',
   'Ramiro llevó una imagen a una reunión donde todos llevaban veinte. Alguien le dijo que faltaba información. «Falta a propósito», contestó. «Prefiero que sea memorable a que sea completo». Al mes, dos personas seguían hablando de esa imagen.',
   'Quiero que se les quede algo.', 'Prefiero que sea memorable a que sea completo.', 3);

