insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('f25820af-6468-4aeb-8d58-9cce6e8079bc', 'trabajo', 'practica', 'Antes de responder',
   'Su compañero le contó un problema largo sobre el proyecto. En vez de responder de inmediato, Marta dijo: «A ver si entendí bien: lo que dices es que el plazo no va a alcanzar». Él asintió, aliviado de sentirse escuchado.',
