insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4e296b0f-86e5-4efd-99d3-a76a81a006ae', 'trabajo', 'practica', 'El silencio en las reuniones',
   'Nadie más lo había mencionado, pero Marina lo notó desde la segunda reunión. «Me percaté de que casi no hablas últimamente, ¿todo bien?», le preguntó a su compañero después, y él por fin contó lo que le pasaba.',
   'Me di cuenta de que casi no hablas últimamente.', 'Me percaté de que casi no hablas últimamente.', 1),
  ('4e296b0f-86e5-4efd-99d3-a76a81a006ae', 'familia', 'emocional', 'La mirada que evitaba',
   'Desde que había vuelto del viaje, algo en su hermano había cambiado. «Me percaté de que evitas mirarme a los ojos», le dijo Bruno una noche, con calma, «¿pasó algo que no me quieras contar?».',
   'Noté que evitas mirarme a los ojos.', 'Me percaté de que evitas mirarme a los ojos.', 2),
  ('4e296b0f-86e5-4efd-99d3-a76a81a006ae', 'social', 'social', 'La foto que lo delató',
   'Al revisar las fotos de la fiesta, Elena se detuvo en una de su amiga. «Recién ahora me percato de lo triste que te veías esa noche», le escribió, «¿por qué no me dijiste nada?».',
   'Recién ahora me doy cuenta de lo triste que te veías.', 'Recién ahora me percato de lo triste que te veías.', 3);

