insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('926e03b0-64df-4905-9ae3-3cd62a5c56f8', 'trabajo', 'practica', 'De la cabeza a dos páginas',
   'Otilia contaba su idea en cada pasillo y cada vez sonaba distinta. Un viernes se sentó dos horas y la plasmó en dos páginas con tres decisiones y un calendario. El lunes ya no tuvo que contarla: la leyeron.',
