insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('09751c85-479a-4edb-9f70-da2d240434eb', 'trabajo', 'practica', 'La línea que nadie miró',
   'El equipo llevaba dos días buscando el origen del problema en todas partes. Crisanta lo encontró y lo dijo sin acusar a nadie: «Estaba precisamente en la línea que no revisamos». Cambiaron el reparto de revisiones esa misma semana.',
   'Estaba justo ahí, en la línea esa que nadie miró.', 'Estaba precisamente en la línea que no revisamos.', 1),
  ('09751c85-479a-4edb-9f70-da2d240434eb', 'familia', 'emocional', 'La semana de los ocho años',
   'Le cambiaron el turno sin avisar y le tocó la noche de un martes cualquiera. Lo malo llegó al mirar el calendario. «Me han puesto de noche precisamente la semana del cumpleaños», dijo en casa. Al día siguiente pidió el cambio y se lo dieron.',
   'Y encima justo esa semana, mira tú qué suerte.', 'Me han puesto de noche precisamente la semana del cumpleaños.', 2),
  ('09751c85-479a-4edb-9f70-da2d240434eb', 'social', 'social', 'El cuadro del pasillo',
   'Los invitados alababan el salón entero y ella sonreía sin decir nada. Cuando alguien señaló un marco pequeño del pasillo, Filomena contestó de golpe: «Ese es precisamente el que más me gusta». La conversación se fue hacia el cuadro y duró toda la sobremesa.',
   'Justo ese, ese es el que más me gusta a mí.', 'Ese es precisamente el que más me gusta.', 3);

