insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('5f42ec5f-b89e-4b60-834e-8ef25b636ab7', 'trabajo', 'practica', 'Dos semanas de aire',
   'El calendario del proyecto estaba clavado al día. Ximena levantó la mano: «Propongo prever dos semanas de margen para el permiso del local». Nadie discutió. En marzo, el permiso tardó doce días y el equipo entregó a tiempo igual.',
   'Por si acaso, dejemos un poquito de aire.', 'Propongo prever dos semanas de margen.', 1),
  ('5f42ec5f-b89e-4b60-834e-8ef25b636ab7', 'familia', 'emocional', 'La cena del sábado',
   'Gonzalo llamó a su hermana antes de la cena familiar. «Sé que el tema de la casa va a salir. Quiero preverlo y hablarlo contigo antes, no delante de todos». Ella se quedó callada un momento y luego dijo: «Gracias por avisarme».',
   'Seguro que sale el tema y acabamos discutiendo.', 'Quiero preverlo y hablarlo antes.', 2),
  ('5f42ec5f-b89e-4b60-834e-8ef25b636ab7', 'entrevista', 'social', 'La pregunta del final',
   'Le preguntaron a Noelia por su peor semana en el puesto anterior. Contó el fallo del servidor y añadió: «Desde entonces preveo siempre un plan alterno para los días de cierre». La entrevistadora anotó la frase entera.',
   'Ahora intento pensar en lo que podría fallar.', 'Desde entonces preveo un plan alterno.', 3);

