insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('8144520d-2902-4a51-ad55-0905d437dbf3', 'trabajo', 'practica', 'Quince minutos',
   'La reunión estaba prevista para una hora y terminó en quince minutos. Petronila lo explicó al equipo sin presumir: «Lo habíamos hablado previamente, así que solo quedaba decidir». Desde entonces la costumbre es llamar antes y reunirse después.',
   'Es que lo habíamos hablado antes, o sea, ya lo sabíamos.', 'Lo habíamos hablado previamente.', 1),
  ('8144520d-2902-4a51-ad55-0905d437dbf3', 'social', 'social', 'La plaza del taller',
   'Dos amigas se plantaron en el taller de cerámica y se quedaron fuera. La tercera lo había leído bien: «Hay que apuntarse previamente en la web». A la semana siguiente fueron las tres, con plaza y con delantal.',
   'Hay que apuntarse antes, creo, en la web esa.', 'Hay que apuntarse previamente en la web.', 2),
  ('8144520d-2902-4a51-ad55-0905d437dbf3', 'familia', 'practica', 'La masa de los domingos',
   'El pan le salía denso cada domingo y no entendía por qué. Su tía le dio la clave por teléfono en una frase: «La masa tiene que reposar previamente una hora en frío». El domingo siguiente el pan subió, y él llamó para contarlo.',
   'Antes hay que dejarla reposar, primero eso.', 'La masa tiene que reposar previamente una hora en frío.', 3);

