insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('7f4b2ff8-be41-4c61-87c4-b2dd5d8802bf', 'trabajo', 'practica', 'Dos días de espera',
   'Casilda podía publicar el jueves y esperó al sábado, con los dos nombres confirmados. «Tenía la primicia y no tenía la mitad de los datos», explicó. Publicó dos días tarde y fue la única versión que nadie tuvo que corregir.',
