insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('ba6a3701-43c7-4d8e-89ae-80bfd0243469', 'social', 'social', 'El silencio que ayudó',
   'Pablo no encontraba las palabras justas, así que simplemente se sentó al lado de su amigo. Después de un rato, su amigo le dijo: «Gracias por reconfortarme, no necesitaba que dijeras nada». Se quedaron así un buen rato más.',
   'Gracias por acompañarme, no necesitaba que dijeras nada.', 'Gracias por reconfortarme, no necesitaba que dijeras nada.', 1),
  ('ba6a3701-43c7-4d8e-89ae-80bfd0243469', 'trabajo', 'emocional', 'El error del penal',
   'El entrenador se acercó al jugador que había fallado, sin decir nada sobre la jugada. «Vengo a reconfortarte, no a explicarte lo que ya sabes que hiciste mal», le dijo, y el jugador respiró más tranquilo antes de volver a la cancha.',
   'Vengo a darte ánimo, no a explicarte lo que ya sabes.', 'Vengo a reconfortarte, no a explicarte lo que ya sabes.', 2),
  ('ba6a3701-43c7-4d8e-89ae-80bfd0243469', 'familia', 'emocional', 'Las llamadas de toda la semana',
   'Después de la mala noticia, sus amigas se turnaban para llamarla cada noche. «Solo quiero reconfortarte, no necesito que me cuentes todo», le dijo una de ellas, y esa frase la ayudó más que cualquier consejo.',
   'Solo quiero acompañarte, no necesito que me cuentes todo.', 'Solo quiero reconfortarte, no necesito que me cuentes todo.', 3);

