insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('72422c99-3a2e-4025-8c89-b697f1089f2f', 'trabajo', 'practica', 'La fecha del correo',
   'En la mesa redonda alguien dijo que nadie había avisado del cambio. Casilda esperó a que terminara la frase, abrió el teléfono y leyó la fecha del correo de marzo. «Replico con esto y no con mi memoria», dijo. Nadie volvió sobre el asunto.',
   'Le contesté ahí mismo, con la fecha.', 'Replico con esto y no con mi memoria.', 1),
  ('72422c99-3a2e-4025-8c89-b697f1089f2f', 'entrevista', 'practica', 'Un minuto',
   'En aquel programa había una regla: quien recibía una crítica tenía un minuto para replicar sin interrupciones. Ximena la usó entera y con dos datos. Al salir, el periodista reconoció que era la mejor regla del formato.',
   'Déjame contestar a eso.', 'Tengo un minuto para replicar.', 2),
  ('72422c99-3a2e-4025-8c89-b697f1089f2f', 'familia', 'emocional', 'La mesa de los domingos',
   'Mi hermano replica a todo lo que dice mi padre, incluso cuando piensa igual. Un domingo se lo dije sin reproche: «No es que discrepes; es que replicas siempre». Se quedó pensando y esa comida acabó tranquila.',
   'Siempre tienes que contestar a todo.', 'No discrepas: replicas siempre.', 3);

