insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('39074563-57cf-4111-bde9-badf5083e9f1', 'trabajo', 'practica', 'Dos firmas antes del martes',
   'Otilia sabía que su propuesta se caería sola en la reunión. Antes del martes la enseñó a dos áreas y les pidió una línea por escrito. Llegó respaldada por finanzas y por almacén, y la discusión duró nueve minutos.',
   'Yo creo que esto se puede hacer, ¿no?', 'Llega respaldada por dos áreas.', 1),
  ('39074563-57cf-4111-bde9-badf5083e9f1', 'familia', 'emocional', 'El taller del hermano',
   'Cuando su hermano alquiló el local, todos dijeron «qué valiente». Gonzalo apareció el sábado con una furgoneta y dos amigos. «Lo de decir que sí está bien», contó después, «pero respaldarlo es aparecer con las manos».',
   'Cuenta conmigo para lo que necesites.', 'Respaldarlo es aparecer con las manos.', 2),
  ('39074563-57cf-4111-bde9-badf5083e9f1', 'entrevista', 'practica', '«Mejoré la atención»',
   'A Ámbar le pidieron un ejemplo y no se quedó en el adjetivo: «Bajamos las quejas de 40 a 12 al mes, y lo puede confirmar mi antigua jefa, que está en la carta». La entrevistadora anotó: afirmación respaldada.',
   'Mejoré mucho la atención al cliente, de verdad.', 'Lo respaldo con la cifra y con quien la firmó.', 3);

