insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4bb6308b-6d14-41a9-9441-a902af830306', 'trabajo', 'practica', 'Sin disculpas de tres líneas',
   'El presupuesto se había quedado a medias en abril. En vez de pedir perdón por la tardanza, Otilia escribió: «Retomo la propuesta que dejamos abierta; el alcance es el mismo y solo movemos fechas». La respuesta llegó el mismo día.',
   'Perdona que te escriba otra vez por el tema aquel.', 'Retomo la propuesta que dejamos abierta.', 1),
  ('4bb6308b-6d14-41a9-9441-a902af830306', 'familia', 'emocional', 'Al día siguiente',
   'La cena terminó con una frase de más y dos silencios. Al mediodía siguiente, Casandra llamó a su hermano: «¿Retomamos lo de anoche, pero con café?». Hablaron media hora y esta vez llegaron hasta el final.',
   'Oye, volvamos a lo de ayer, que quedó feo.', '¿Retomamos lo de anoche?', 2),
  ('4bb6308b-6d14-41a9-9441-a902af830306', 'social', 'social', 'El viaje pendiente',
   'El plan del viaje llevaba dormido desde enero en el grupo. Leandro escribió una línea: «Retomo el viaje: ¿mayo o junio?». En dos horas había fechas, presupuesto y dos personas buscando casa.',
   'A ver si volvemos a hablar de lo del viaje.', 'Retomo el viaje: ¿mayo o junio?', 3);

