insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('89b8269c-e080-4f30-ad1d-1a1599c3fc18', 'social', 'social', 'El verano en la playa',
   'Todo el grupo hablaba de lo mismo esa semana: la instructora de surf y el chico del bar no se despegaban. «Es un romance de verano», dijo alguien, «va a durar lo que dura el sol, pero mientras tanto se les ve felices».',
   'Tienen algo, aunque no le pongan etiqueta.', 'Tienen un romance de verano.', 1),
  ('89b8269c-e080-4f30-ad1d-1a1599c3fc18', 'trabajo', 'social', 'El secreto de la oficina',
   'Nadie lo confirmaba, pero todos lo sabían: llevaban meses saliendo del trabajo por separado, con quince minutos de diferencia. «Ese romance de oficina no es tan secreto como creen», le dijo una colega a otra, sin poder disimular la sonrisa.',
   'Ese rollo de oficina no es tan secreto como creen.', 'Ese romance de oficina no es tan secreto como creen.', 2),
  ('89b8269c-e080-4f30-ad1d-1a1599c3fc18', 'familia', 'emocional', 'La foto que lo delató',
   'Nadie sabía nada hasta que Elena subió una foto sin pensarlo dos veces. Su madre la llamó esa misma tarde: «¿Me vas a contar de este romance o me entero por redes de todo?», preguntó, entre curiosa y divertida.',
   '¿Me vas a contar de esto o me entero por redes?', '¿Me vas a contar de este romance o me entero por redes?', 3);

