insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('cae177d6-720d-448d-9cd6-626364ed27a2', 'trabajo', 'social', 'La nueva del equipo de diseño',
   'Marina notó que Iván pasaba por el área de diseño más de lo normal. «Lleva semanas rondándola», le comentó a otra compañera, «a ver cuándo se anima a invitarla un café».',
