insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('8830b5c5-73b4-42f7-865a-db2da23f5827', 'trabajo', 'practica', 'Diez minutos de silencio',
   'Aurora presentó el plan y esperó. Nadie dijo nada. Al contarlo después, en vez de exagerar, midió el hecho: «Nadie hizo siquiera una pregunta». Su compañero entendió al instante el tamaño del problema y se ofreció a repasarlo con ella.',
   'No dijeron nada de nada, en serio.', 'Nadie hizo siquiera una pregunta.', 1),
  ('8830b5c5-73b4-42f7-865a-db2da23f5827', 'familia', 'emocional', 'La comida del domingo',
   'Dionisio llegó cuando ya estaban recogiendo. Su hermana no le gritó: solo puso el dato encima de la mesa. «No probaste siquiera el primer plato», dijo, y siguió fregando. Él se quedó de pie, pensando en la hora que había salido de casa.',
   'No comiste nada de nada, como siempre.', 'No probaste siquiera el primer plato.', 2),
  ('8830b5c5-73b4-42f7-865a-db2da23f5827', 'social', 'social', 'La terraza de los jueves',
   'Quedaron cinco y hablaron cuatro. Tamara lo comentó al día siguiente, sin dramatizar: «Estuvo tres horas y no levantó la vista siquiera para pedir el café». No hizo falta añadir nada más; el grupo decidió hablar con él de frente.',
   'Es que no soltó el móvil ni un segundo, tela.', 'No levantó la vista siquiera para pedir el café.', 3);

