insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('b9a67456-001f-413b-ad3e-70057ffe119f', 'social', 'practica', 'El grupo del barrio',
   'Cuando el auto de Hugo se averió justo antes de un viaje importante, sus vecinos armaron un chat en minutos: uno le prestó el suyo, otro llamó a un mecánico de confianza y otro se ofreció a acompañarlo al taller. Hugo no lo podía creer.',
   'Todos se pusieron de mi lado enseguida.', 'Fueron muy solidarios conmigo.', 1),
  ('b9a67456-001f-413b-ad3e-70057ffe119f', 'trabajo', 'emocional', 'La carga compartida',
   'Cuando Paula tuvo que viajar de urgencia a otra ciudad por un asunto familiar, sus compañeros se repartieron sus pendientes sin que ella lo pidiera. «No estás sola en esto», le dijo su jefa. Paula volvió al trabajo días después y encontró todo en orden, como si nunca se hubiera ido.',
   'Sentí que hicieron mío el problema.', 'Fueron muy solidarios en un momento difícil.', 2),
  ('b9a67456-001f-413b-ad3e-70057ffe119f', 'familia', 'social', 'La tienda de la tía',
   'Cuando la tienda de su tía Marta empezó a perder clientes, toda la familia decidió comprar ahí, aunque tuvieran que dar una vuelta más larga. «Es lo mínimo que podemos hacer», dijo su primo Andrés. Marta lloró la primera vez que los vio entrar juntos.',
   'Se portaron como si el problema fuera de todos.', 'Fueron muy solidarios con ella.', 3);

