insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('083d22a5-a12f-4525-997d-e56ebc07ef74', 'trabajo', 'practica', 'Doce días',
   'Las dos ofertas parecían iguales hasta que Ramiro puso los plazos uno debajo del otro. «Aquí hay una diferencia sustancial: doce días», dijo. La sala dejó de discutir el precio y empezó a discutir el calendario.',
