insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('d6a31be5-eb68-4fe1-b4b6-b5f61269e571', 'trabajo', 'practica', 'La frase cortada',
   'En el programa cortaron la frase de Nerea por la mitad. Ella no gritó ni pidió disculpas ajenas. Escribió dos líneas: «Han tergiversado la respuesta; aquí está el minuto completo». Adjuntó el enlace y no volvió a hablar del tema.',
   'Me han sacado de contexto.', 'Han tergiversado la respuesta: aquí está el minuto completo.', 1),
  ('d6a31be5-eb68-4fe1-b4b6-b5f61269e571', 'familia', 'emocional', 'Llegaré tarde',
   'Dije que llegaría tarde y a mi madre le llegó que no pensaba ir. Cuando lo aclaramos, mi hermana se rio: «Ya sabes cómo lo cuenta». Lo dije en voz alta y sin enfadarme: «No lo cuenta mal, lo tergiversa». La siguiente vez escribí en el grupo.',
   'Lo cuenta todo al revés.', 'No lo cuenta mal: lo tergiversa.', 2),
  ('d6a31be5-eb68-4fe1-b4b6-b5f61269e571', 'entrevista', 'practica', 'La grabación completa',
   'Antes de responder a la pregunta difícil, Ximena miró al periodista. «Contesto entero», dijo, «y si tergiversan esto, pediré la grabación completa». Contestó sin rodeos y el titular del día siguiente decía lo mismo que ella.',
   'Espero que no me saquen de contexto.', 'Si tergiversan esto, pediré la grabación completa.', 3);

